-- 210: the rest of the database for agents. 55+ new read-only `analytics` views over every subject area that was not exposed yet, plus the catalog and the metric glossary.
--
-- Domains: marketing, attribution, orders, creative, tags, priorities, production, projection, inventory, cohorts, pacing, competitors, pipeline (analytics.catalog lists them).
-- Everything above the "comments" marker is hand-written DDL; everything below it is GENERATED by `python scripts/gen_schema_doc.py --emit-migration 210` from
-- docs/schema/descriptions.py: the catalog and metric_glossary views (their rows ARE the descriptions) and the COMMENT ON statements. Additive and idempotent
-- (CREATE OR REPLACE VIEW, COMMENT ON). Once applied this file is immutable: a later view change goes in a NEW migration, a later change of a description or of the
-- metric list in a NEW migration written with `gen_schema_doc.py --comments 210` and `--catalog-sql`.
--
-- Same rules as 013: analytics = views over public tables, owned by the migration role, so SELECT on a view needs no privilege on the table behind it.
-- Joins are pre-resolved (tags carry the tracker row, product and taxonomy line), ids that mean nothing outside the app are replaced by slugs and names, and every view
-- is a plain select (a window function only where a derived column is the point), so an agent's query stays well under the 30 s cut.
--
-- NOT in here on purpose (the reason for each is in the PR and in docs/DATA_SCHEMA.md):
--   secrets / auth: feed_oauth (refresh token), api_keys (key hashes), creative_priorities_vendor_links (vendor link tokens), creative_priorities_views (view tokens + payload),
--     schema_migrations; and no APP_USERS or session store exists in the database.
--   audit trails that hold login names or IPs: proj_audit, proj_scenario_history, proj_supply_history, proj_upload_history, proj_cohort_uploads, proj_units_loads,
--     creative_launch_audit. Columns that name a person (actor, *_by, requested_by, saved_by) are left out of the views that read otherwise safe tables.
--   the launch tables (creative_launch_*): Page / account ids, jobs and plans for the dark Meta-write path.
--   raw JSON blobs: proj_scenarios.params (read through projection_levers, lever by lever), creative_priorities_snapshots.rows / thresholds / baselines / stats (flattened),
--     proj_pnl_* jsonb that is not a model input, extra on ad_tags, projected_days on the Amazon month-to-date snapshots.
--   image bytes (creative_assets) and shadow twins of the feeds (proj_feedx_*), which only exist to be compared with proj_feed_*.

CREATE SCHEMA IF NOT EXISTS analytics;


-- ---------------------------------------------------------------------------------------------------------------- attribution: which orders each source gets credit for

-- Last-click attribution by ad source (Meta Ads, Google Ads, ...) per Pacific day: exclusive per order, unlike the any-click 30-day credit in meta_ad_daily.
CREATE OR REPLACE VIEW analytics.attribution_source_daily AS
SELECT a.day,
       a.ad_source,
       a.nc_orders AS new_customers,
       a.nc_rev    AS new_customer_revenue,
       a.orders,
       a.rev       AS order_revenue,
       a.loaded_at
FROM public.proj_feed_attribution a;

-- Upstack any-click 30-day new customers on Scaling and Testing Meta campaigns per day.
CREATE OR REPLACE VIEW analytics.attribution_anyclick_daily AS
SELECT a.day,
       a.stage,
       a.nc     AS new_customers,
       a.nc_rev AS new_customer_revenue,
       a.loaded_at
FROM public.proj_feed_anyclick a;

-- Upstack-credited orders the build could not tie to a Meta ad: in orders_daily, in no ad-level row.
CREATE OR REPLACE VIEW analytics.attribution_unmapped_daily AS
SELECT u.day,
       u.campaign,
       u.ad,
       u.reason,
       u.nc     AS new_customers,
       u.nc_rev AS new_customer_revenue,
       u.orders,
       u.rev    AS order_revenue
FROM public.upstack_unmapped_daily u;


-- ---------------------------------------------------------------------------------------------------------------- orders: actual revenue, new customers, Amazon, traffic

-- orders_daily plus the tax collected and the refunds of each Pacific day (the two columns pacing uses to go from gross to net).
CREATE OR REPLACE VIEW analytics.orders_daily_detail AS
SELECT o.day,
       o.nc_rev       AS new_customer_revenue,
       o.rc_rev       AS returning_customer_revenue,
       o.nc_orders    AS new_customers,
       o.total_rev    AS total_revenue,
       o.total_orders AS orders,
       o.tax,
       o.refunds,
       o.loaded_at
FROM public.proj_feed_orders o;

-- Actual Shopify first-order revenue and new customers per Pacific day by the order's largest product line (not Meta-attributed).
CREATE OR REPLACE VIEW analytics.orders_by_product_daily AS
SELECT p.day,
       p.product,
       p.nc_rev    AS new_customer_revenue,
       p.nc_orders AS new_customers,
       p.loaded_at
FROM public.proj_feed_nc_product p;

-- Actual new-customer revenue and first orders by Pacific day and clock hour (the share curve behind the NC revenue today card).
CREATE OR REPLACE VIEW analytics.orders_hourly AS
SELECT h.day,
       h.hour,
       h.nc_rev    AS new_customer_revenue,
       h.nc_orders AS new_customers,
       h.loaded_at
FROM public.proj_feed_nc_hourly h;

-- Amazon.com + B2B sales and Amazon Ads (de-duplicated) by purchase day.
CREATE OR REPLACE VIEW analytics.amazon_daily AS
SELECT a.day,
       a.orders,
       a.units,
       a.revenue,
       a.nc_orders AS new_customer_orders,
       a.nc_rev    AS new_customer_revenue,
       a.ad_spend,
       a.attributed_sales,
       a.clicks,
       a.impressions,
       a.loaded_at
FROM public.proj_feed_amazon a;

-- Pixel-tracked visitors, new visitors and sessions per day (unique within the day, not additive across days).
CREATE OR REPLACE VIEW analytics.site_traffic_daily AS
SELECT t.day,
       t.new_visitors,
       t.visitors,
       t.sessions,
       t.loaded_at
FROM public.proj_feed_traffic t;


-- ---------------------------------------------------------------------------------------------------------------- marketing: longer history and product splits of the pacing feeds

-- Meta and Google spend and platform-reported conversions per day from 2025-01-01 (Upstack ad-platform feed): the longest spend history.
CREATE OR REPLACE VIEW analytics.platform_daily_history AS
SELECT p.day,
       CASE WHEN p.platform LIKE 'Meta%' THEN 'meta' WHEN p.platform LIKE 'Google%' THEN 'google' ELSE p.platform END AS platform,
       p.platform AS platform_label,
       p.spend,
       p.link_clicks,
       p.clicks,
       p.purchases          AS own_purchases,
       p.purchase_value     AS own_revenue,
       p.nc_purchases       AS own_new_customer_purchases,
       p.nc_purchase_value  AS own_new_customer_revenue,
       p.loaded_at
FROM public.proj_feed_platform p;

-- Meta spend and link clicks per day by product (campaign name, else ad set name, else ad name, else Other), from 2025-01-01.
CREATE OR REPLACE VIEW analytics.meta_product_daily AS
SELECT d.day,
       d.product,
       d.source,
       d.spend,
       d.link_clicks,
       d.loaded_at
FROM public.proj_feed_meta_product d
WHERE d.source = 'app'
   OR NOT EXISTS (SELECT 1 FROM public.proj_feed_meta_product a WHERE a.day = d.day AND a.source = 'app');

-- Unique outbound clicks per product, de-duplicated across the product's ad sets, at day / week / month grain (from 2026-07-05).
CREATE OR REPLACE VIEW analytics.meta_product_reach AS
SELECT r.grain,
       r.period_key,
       r.period_start,
       r.period_end,
       r.product,
       r.unique_outbound_clicks,
       r.loaded_at
FROM public.proj_feed_product_reach r;

-- Meta bid settings per day, summed: spend on cost-cap / bid-cap ad sets and on ROAS-floor ad sets, with the spend-weighted bid sums.
CREATE OR REPLACE VIEW analytics.meta_bids_daily AS
SELECT b.day,
       b.spend,
       b.capped_spend,
       b.spend_x_cap   AS spend_times_cap,
       b.floor_spend,
       b.spend_x_floor AS spend_times_floor,
       b.loaded_at
FROM public.proj_feed_bids b;


-- ---------------------------------------------------------------------------------------------------------------- pacing: the daily pacing inputs

-- Today's Meta spend, Google spend, new-customer revenue and new customers so far, one snapshot per hourly pull.
CREATE OR REPLACE VIEW analytics.pacing_live_today AS
SELECT s.pulled_at,
       s.day,
       s.pacific_time,
       s.meta_spend,
       s.google_spend,
       s.total_spend,
       s.nc_rev    AS new_customer_revenue,
       s.nc_orders AS new_customers
FROM public.proj_live_today_snapshots s;

-- Completed Amazon month-to-date revenue per run: reported days plus the missing days projected at the trailing 7-day average.
CREATE OR REPLACE VIEW analytics.pacing_amazon_month_to_date AS
SELECT s.snapshot_day,
       s.month,
       s.computed_at,
       s.data_through,
       s.last_actual_day,
       s.days_actual,
       s.days_projected,
       s.daily_rate,
       s.actual_mtd,
       s.projected_mtd,
       s.status,
       s.method,
       s.flags,
       s.partial_topup,
       s.lag_days,
       s.rate_source,
       s.note
FROM public.proj_amazon_mtd_snapshots s;

-- Meta time-of-day spend curve (hourly spend of the last 30 days): the typed input behind the intraday projection.
CREATE OR REPLACE VIEW analytics.pacing_hourly_spend_curve AS
SELECT h.hour,
       h.spend_30d,
       h.days_in_curve,
       h.note,
       h.updated_at
FROM public.proj_pacing_hourly h;

-- The pacing levers (ratios and estimates the pacing page applies), one row per lever.
CREATE OR REPLACE VIEW analytics.pacing_levers AS
SELECT l.key AS lever,
       l.value,
       l.note,
       l.updated_at
FROM public.proj_feed_levers l;

-- Monthly Meta spend from ad_daily, read by the projection drivers.
CREATE OR REPLACE VIEW analytics.pacing_meta_spend_monthly AS
SELECT m.month,
       m.spend,
       m.days,
       m.last_day
FROM public.proj_meta_spend_monthly m;


-- ---------------------------------------------------------------------------------------------------------------- pipeline: health of the feeds and the nightly projection refresh

-- One row per pacing feed: its mode (sheet / shadow / direct), what was last loaded and through which day.
CREATE OR REPLACE VIEW analytics.pipeline_feeds AS
SELECT r.feed,
       COALESCE(c.mode, 'sheet') AS mode,
       r.source,
       r.loaded_at,
       r.rows_loaded,
       r.first_day,
       r.last_day,
       r.note
FROM public.proj_feed_runs r
LEFT JOIN public.proj_feed_config c ON c.feed = r.feed;

-- One row per direct pull attempt of a feed (any mode).
CREATE OR REPLACE VIEW analytics.pipeline_feed_attempts AS
SELECT a.id,
       a.feed,
       a.mode,
       a.source,
       a.started_at,
       a.finished_at,
       a.status,
       a.rows,
       a.first_day,
       a.last_day,
       a.note
FROM public.proj_feed_attempts a;

-- Latest verification result per feed and day: the direct pull compared with the sheet-fed table.
CREATE OR REPLACE VIEW analytics.pipeline_feed_verify AS
SELECT v.feed,
       v.day,
       v.status,
       v.n_keys,
       v.n_bad,
       v.worst_col,
       v.worst_abs,
       v.worst_rel,
       v.detail,
       v.checked_at
FROM public.proj_feed_verify v;

-- One row per projection module per run of the nightly projection refresh.
CREATE OR REPLACE VIEW analytics.pipeline_refresh_runs AS
SELECT r.id,
       r.module,
       r.started_at,
       r.finished_at,
       r.status,
       r.rows,
       r.data_through,
       left(r.error, 300) AS error
FROM public.proj_refresh_runs r;

-- The hourly health checks that fired: when each problem opened, was last seen, was last alerted and whether it resolved.
CREATE OR REPLACE VIEW analytics.pipeline_alerts AS
SELECT a.check_id,
       a.first_seen,
       a.last_seen,
       a.last_alerted,
       a.resolved_at,
       a.alert_count,
       left(a.last_message, 300) AS last_message
FROM public.alert_state a;


-- ---------------------------------------------------------------------------------------------------------------- projection: scenarios, levers, monthly inputs and actuals (the model's outputs are computed in the app, not stored)

-- The named scenarios (lever sets) of the Projection module; 'current' is the plan of record.
CREATE OR REPLACE VIEW analytics.projection_scenarios AS
SELECT s.id AS scenario_id,
       s.slug,
       s.name,
       s.base_slug,
       s.is_default,
       s.version,
       s.frozen,
       s.created_at,
       s.updated_at,
       s.archived_at
FROM public.proj_scenarios s;

-- Every lever of every live scenario, one row per (scenario, module, lever): financing terms, driver rates, cohort levers, pacing and inventory settings.
CREATE OR REPLACE VIEW analytics.projection_levers AS
SELECT s.slug  AS scenario_slug,
       m.key   AS module,
       l.key   AS lever,
       l.value
FROM public.proj_scenarios s
CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(s.params) = 'object' THEN s.params ELSE '{}'::jsonb END) m
CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(m.value) = 'object' THEN m.value ELSE '{}'::jsonb END) l
WHERE s.archived_at IS NULL;

-- The monthly cells a scenario itself holds (inputs and overrides), one row per (scenario, line, month); cells it inherits from its base scenario are not repeated.
CREATE OR REPLACE VIEW analytics.projection_series AS
SELECT s.slug AS scenario_slug,
       x.line_key,
       x.month,
       x.value,
       x.kind,
       x.note,
       x.updated_at
FROM public.proj_series x
JOIN public.proj_scenarios s ON s.id = x.scenario_id
WHERE s.archived_at IS NULL;

-- Scenario-independent monthly facts: QuickBooks P&L lines (pnl.<line>), spend by channel and other loaded actuals.
CREATE OR REPLACE VIEW analytics.projection_actuals AS
SELECT a.line_key,
       a.month,
       a.value,
       a.source,
       a.loaded_at
FROM public.proj_actuals a;

-- How each P&L line is projected: ordered segments of fixed / carry / rate modes (a model input).
CREATE OR REPLACE VIEW analytics.projection_pnl_drivers AS
SELECT d.line_key,
       d.segments,
       d.note,
       d.source,
       d.updated_at
FROM public.proj_pnl_drivers d;

-- P&L engine settings (rate window, inflation, headcount, COGS, enterprise value), one row per setting.
CREATE OR REPLACE VIEW analytics.projection_pnl_settings AS
SELECT s.key AS setting,
       s.value,
       s.note,
       s.updated_at
FROM public.proj_pnl_settings s;

-- QuickBooks account name to P&L line key map used when an export is loaded.
CREATE OR REPLACE VIEW analytics.projection_pnl_account_map AS
SELECT m.account,
       m.line_key,
       m.note,
       m.updated_at
FROM public.proj_pnl_qb_map m;

-- Landed unit cost by SKU and the sales mix that weights it (the forward COGS model).
CREATE OR REPLACE VIEW analytics.projection_cogs_sku AS
SELECT c.sku,
       c.label,
       c.china_unit_cost,
       c.us_unit_cost,
       c.sales_mix,
       c.in_stock_qty,
       c.sort,
       c.note,
       c.updated_at
FROM public.proj_pnl_cogs_sku c;

-- Vendor retainers, current vs proposed, per month.
CREATE OR REPLACE VIEW analytics.projection_vendor_retainers AS
SELECT v.vendor,
       v.current_monthly,
       v.proposed_monthly,
       v.sort,
       v.note
FROM public.proj_pnl_vendors v;


-- ---------------------------------------------------------------------------------------------------------------- inventory: purchase orders, transfers, stock and units

-- Purchase orders (planned and actual): units, vendor, dates, deposit state, unit cost.
CREATE OR REPLACE VIEW analytics.inventory_purchase_orders AS
SELECT p.id AS po_id,
       p.po_number,
       p.product,
       p.vendor,
       p.warehouse,
       p.units,
       p.order_date,
       p.land_date,
       p.status,
       p.deposit_paid,
       p.shipping_paid,
       p.balance_paid,
       p.deposit_pct,
       p.unit_cost,
       p.note,
       p.source,
       p.created_at,
       p.updated_at
FROM public.proj_po p;

-- Planned and actual transfers from the US warehouse to FBA.
CREATE OR REPLACE VIEW analytics.inventory_fba_transfers AS
SELECT t.id AS transfer_id,
       t.transfer_no,
       t.product,
       t.units,
       t.ship_date,
       t.receive_date,
       t.status,
       t.note,
       t.source,
       t.created_at,
       t.updated_at
FROM public.proj_fba_transfer t;

-- Vendor lead times, minimum order quantities and default warehouses.
CREATE OR REPLACE VIEW analytics.inventory_vendor_lead_times AS
SELECT v.vendor,
       v.lead_weeks,
       v.moq_units,
       v.default_warehouse,
       v.note,
       v.updated_at
FROM public.proj_vendor_lead v;

-- Vendor unit cost per product and the default deposit share of a new purchase order.
CREATE OR REPLACE VIEW analytics.inventory_vendor_costs AS
SELECT v.vendor,
       v.product,
       v.unit_cost,
       v.deposit_pct,
       v.note,
       v.updated_at
FROM public.proj_vendor_cogs v;

-- Unit cost used to value stock on hand (landed cost per SKU).
CREATE OR REPLACE VIEW analytics.inventory_product_costs AS
SELECT c.product,
       c.sku,
       c.china_unit_cost,
       c.us_unit_cost,
       c.note,
       c.updated_at
FROM public.proj_product_cost c;

-- Reorder parameters per location and product: lead days, safety days, minimum order quantity.
CREATE OR REPLACE VIEW analytics.inventory_reorder_params AS
SELECT r.location,
       r.product,
       r.lead_days,
       r.safety_days,
       r.moq_units,
       r.updated_at
FROM public.proj_reorder_param r;

-- Stock on hand per location and product, one row per count.
CREATE OR REPLACE VIEW analytics.inventory_stock_counts AS
SELECT s.location,
       s.product,
       s.as_of,
       s.on_hand,
       s.allocated,
       s.inbound_per_3pl,
       s.estimate,
       s.note,
       s.created_at
FROM public.proj_stock_snapshot s;

-- Stock on hand and allocated per location and product, one snapshot per day (Warehance for the US warehouse).
CREATE OR REPLACE VIEW analytics.inventory_stock_daily AS
SELECT d.location,
       d.product,
       d.as_of,
       d.on_hand,
       d.allocated,
       d.source,
       d.loaded_at
FROM public.proj_demand_snapshot d;

-- Units shipped or sold per day by location (US 3PL, FBA, overseas 3PL) and product: the demand history.
CREATE OR REPLACE VIEW analytics.inventory_units_daily AS
SELECT u.location,
       u.product,
       u.day,
       u.units,
       u.source,
       u.is_estimate,
       u.loaded_at
FROM public.proj_units_daily u;

-- Monthly units history for months older than the daily window.
CREATE OR REPLACE VIEW analytics.inventory_units_monthly AS
SELECT u.location,
       u.product,
       u.month,
       u.units,
       u.source,
       u.loaded_at
FROM public.proj_units_monthly u;

-- International units by destination country and month (informational split of overseas 3PL volume).
CREATE OR REPLACE VIEW analytics.inventory_units_by_country AS
SELECT u.month,
       u.country,
       u.units,
       u.days,
       u.source,
       u.loaded_at
FROM public.proj_units_country u;


-- ---------------------------------------------------------------------------------------------------------------- cohorts: acquisition cohorts and the retention curves

-- One row per acquisition month: new customers, first-order dollars, CAC, 90-day repeat rate, payback as exported.
CREATE OR REPLACE VIEW analytics.cohorts_monthly AS
SELECT c.cohort_month,
       c.new_customers,
       c.first_order_per_customer,
       c.new_customers * c.first_order_per_customer AS first_order_revenue,
       c.first_order_realized,
       c.repeat_90d,
       c.cac,
       c.payback_months,
       c.nc_rev_reference,
       c.source,
       c.loaded_at
FROM public.proj_cohorts c;

-- Cumulative dollars per cohort customer at each age, with the monthly increment, its ratio to the first order and the cohort's recency rank at that age (the inputs of the Live curve).
CREATE OR REPLACE VIEW analytics.cohorts_curve_cumulative AS
WITH x AS (
  SELECT c.cohort_month,
         c.age,
         c.cum_per_customer,
         k.new_customers,
         k.first_order_per_customer,
         CASE WHEN c.age = 1 THEN NULLIF(k.first_order_per_customer, 0) ELSE NULLIF(p.cum_per_customer, 0) END AS prev_cum
  FROM public.proj_cohort_cum c
  JOIN public.proj_cohorts k ON k.cohort_month = c.cohort_month
  LEFT JOIN public.proj_cohort_cum p ON p.cohort_month = c.cohort_month AND p.age = c.age - 1
), y AS (
  SELECT x.*,
         CASE WHEN NULLIF(x.cum_per_customer, 0) IS NOT NULL AND x.prev_cum IS NOT NULL THEN x.cum_per_customer - x.prev_cum END AS increment
  FROM x
), z AS (
  SELECT y.*,
         CASE WHEN y.increment IS NOT NULL AND y.first_order_per_customer > 0 THEN y.increment / y.first_order_per_customer END AS increment_ratio
  FROM y
)
SELECT z.cohort_month,
       z.age,
       z.new_customers,
       z.first_order_per_customer,
       z.cum_per_customer,
       z.increment,
       z.increment_ratio,
       CASE WHEN z.increment_ratio IS NOT NULL AND z.increment_ratio <> 0 AND z.new_customers > 0
            THEN row_number() OVER (PARTITION BY z.age, (z.increment_ratio IS NOT NULL AND z.increment_ratio <> 0 AND z.new_customers > 0)
                                    ORDER BY z.cohort_month DESC) END AS usable_rank
FROM z;

-- Goal retention curve snapshots: repeat dollars per $1 of first-order revenue by age 1..60; the newest snapshot is the active one.
CREATE OR REPLACE VIEW analytics.cohorts_curve_goal AS
SELECT g.snapshot_id,
       g.snapshot_date,
       g.age,
       g.value,
       g.note,
       g.saved_at,
       g.restored_from,
       g.snapshot_id = (SELECT max(snapshot_id) FROM public.proj_curve_goal) AS is_active
FROM public.proj_curve_goal g;


-- ---------------------------------------------------------------------------------------------------------------- creative: derived roll-ups per ad family, test to scale, content

-- Meta spend, purchases and revenue per creative family (tracker family) per day and stage, in three bases and for all ads or only the ads that were active.
CREATE OR REPLACE VIEW analytics.creative_family_daily AS
SELECT d.basis, d.ads_scope, d.family_key, p.slug AS product_slug, d.day, d.stage, d.spend, d.purchases, d.revenue, d.link_clicks, d.impressions
FROM (
SELECT 'meta'::text AS basis, 'all_ads'::text AS ads_scope, f.family_key, f.day, f.stage, f.spend, f.purchases, f.revenue, f.link_clicks, f.impressions
FROM public.family_daily f
UNION ALL
SELECT 'upstack_new_customers'::text AS basis, 'all_ads'::text AS ads_scope, f.family_key, f.day, f.stage, f.spend, f.purchases, f.revenue, f.link_clicks, f.impressions
FROM public.family_daily_upstack_nc f
UNION ALL
SELECT 'upstack_all_orders'::text AS basis, 'all_ads'::text AS ads_scope, f.family_key, f.day, f.stage, f.spend, f.purchases, f.revenue, f.link_clicks, f.impressions
FROM public.family_daily_upstack_all f
UNION ALL
SELECT 'meta'::text AS basis, 'active_ads'::text AS ads_scope, f.family_key, f.day, f.stage, f.spend, f.purchases, f.revenue, f.link_clicks, f.impressions
FROM public.family_daily_active f
UNION ALL
SELECT 'upstack_new_customers'::text AS basis, 'active_ads'::text AS ads_scope, f.family_key, f.day, f.stage, f.spend, f.purchases, f.revenue, f.link_clicks, f.impressions
FROM public.family_daily_active_upstack_nc f
UNION ALL
SELECT 'upstack_all_orders'::text AS basis, 'active_ads'::text AS ads_scope, f.family_key, f.day, f.stage, f.spend, f.purchases, f.revenue, f.link_clicks, f.impressions
FROM public.family_daily_active_upstack_all f
) d
LEFT JOIN (SELECT DISTINCT ON (m.family_key) m.family_key, pr.slug
           FROM public.ad_metrics m JOIN public.products pr ON pr.id = m.product_id
           WHERE m.is_first_row ORDER BY m.family_key, m.tracker_row_id) p ON p.family_key = d.family_key;

-- Since-launch, 7-day and 30-day spend, purchases and revenue per tracker row (on the first row of each ad family), in three bases.
CREATE OR REPLACE VIEW analytics.creative_family_metrics AS
SELECT m.basis, m.tracker_row_id, t.concept_id, m.family_key, pr.slug AS product_slug, m.is_first_row, m.launch_date,
       m.spend_launch, m.purchases_launch, m.revenue_launch, m.spend_7d, m.purchases_7d, m.revenue_7d, m.spend_30d, m.purchases_30d, m.revenue_30d,
       m.live, m.impressions_launch, m.clicks_launch, m.ads_active_count, m.spend_launch_active, m.purchases_launch_active, m.revenue_launch_active,
       m.impressions_launch_active, m.clicks_launch_active, m.live_active, m.built_at
FROM (
SELECT 'meta'::text AS basis, m.tracker_row_id, m.family_key, m.is_first_row, m.launch_date, m.spend_launch, m.purchases_launch, m.revenue_launch, m.spend_7d, m.purchases_7d, m.revenue_7d, m.spend_30d, m.purchases_30d, m.revenue_30d, m.live, m.impressions_launch, m.clicks_launch, m.ads_active_count, m.spend_launch_active, m.purchases_launch_active, m.revenue_launch_active, m.impressions_launch_active, m.clicks_launch_active, m.live_active, m.built_at, m.product_id
FROM public.ad_metrics m
UNION ALL
SELECT 'upstack_new_customers'::text AS basis, m.tracker_row_id, m.family_key, m.is_first_row, m.launch_date, m.spend_launch, m.purchases_launch, m.revenue_launch, m.spend_7d, m.purchases_7d, m.revenue_7d, m.spend_30d, m.purchases_30d, m.revenue_30d, m.live, m.impressions_launch, m.clicks_launch, m.ads_active_count, m.spend_launch_active, m.purchases_launch_active, m.revenue_launch_active, m.impressions_launch_active, m.clicks_launch_active, m.live_active, m.built_at, m.product_id
FROM public.ad_metrics_upstack_nc m
UNION ALL
SELECT 'upstack_all_orders'::text AS basis, m.tracker_row_id, m.family_key, m.is_first_row, m.launch_date, m.spend_launch, m.purchases_launch, m.revenue_launch, m.spend_7d, m.purchases_7d, m.revenue_7d, m.spend_30d, m.purchases_30d, m.revenue_30d, m.live, m.impressions_launch, m.clicks_launch, m.ads_active_count, m.spend_launch_active, m.purchases_launch_active, m.revenue_launch_active, m.impressions_launch_active, m.clicks_launch_active, m.live_active, m.built_at, m.product_id
FROM public.ad_metrics_upstack_all m
) m
LEFT JOIN public.tracker_rows t ON t.id = m.tracker_row_id
LEFT JOIN public.products pr ON pr.id = m.product_id;

-- Meta ad families that run on no Creative Tracker row, with their spend and results, in three bases.
CREATE OR REPLACE VIEW analytics.creative_unmatched_meta AS
SELECT 'meta'::text AS basis, u.meta_family_key AS family_key, u.meta_family AS family_name, pr.slug AS product_slug, u.spend_7d, u.purchases_7d, u.revenue_7d, u.spend_30d, u.purchases_30d, u.revenue_30d, u.spend_all, u.purchases_all, u.revenue_all, u.live, u.spend_launch, u.purchases_launch, u.revenue_launch, u.impressions_launch, u.clicks_launch, u.product_source
FROM public.unmatched_meta u LEFT JOIN public.products pr ON pr.id = u.product_id
UNION ALL
SELECT 'upstack_new_customers'::text AS basis, u.meta_family_key AS family_key, u.meta_family AS family_name, pr.slug AS product_slug, u.spend_7d, u.purchases_7d, u.revenue_7d, u.spend_30d, u.purchases_30d, u.revenue_30d, u.spend_all, u.purchases_all, u.revenue_all, u.live, u.spend_launch, u.purchases_launch, u.revenue_launch, u.impressions_launch, u.clicks_launch, u.product_source
FROM public.unmatched_meta_upstack_nc u LEFT JOIN public.products pr ON pr.id = u.product_id
UNION ALL
SELECT 'upstack_all_orders'::text AS basis, u.meta_family_key AS family_key, u.meta_family AS family_name, pr.slug AS product_slug, u.spend_7d, u.purchases_7d, u.revenue_7d, u.spend_30d, u.purchases_30d, u.revenue_30d, u.spend_all, u.purchases_all, u.revenue_all, u.live, u.spend_launch, u.purchases_launch, u.revenue_launch, u.impressions_launch, u.clicks_launch, u.product_source
FROM public.unmatched_meta_upstack_all u LEFT JOIN public.products pr ON pr.id = u.product_id;

-- Test to scale: one row per creative family with its testing and scaling spend, when it moved from a Testing to a Scaling campaign and how it did, in three bases.
CREATE OR REPLACE VIEW analytics.creative_stage_moves AS
SELECT 'meta'::text AS basis, s.family_key, s.tracker_row_id, s.product_slug, s.product_name, s.concept_id, s.display, s.ad_type, s.tracker_status, s.tracker_launch_date, s.cluster, s.icp, s.pain AS pain_point, s.data_start, s.data_through, s.path, s.began_in_testing, s.moved, s.first_day, s.testing_first_day, s.scaling_first_day, s.last_spend_day, s.scaling_last_day, s.days_in_test, s.launched_before_data_start, s.test_spend, s.test_purchases, s.test_revenue, s.test_link_clicks, s.test_days, s.test_after_spend, s.scale_spend, s.scale_purchases, s.scale_revenue, s.scale_link_clicks, s.scale_days, s.unclassified_spend, s.last7_spend, s.last7_purchases, s.last7_revenue, s.last7_scale_spend, s.last7_scale_purchases, s.last7_scale_revenue, s.live, s.live_scaling, s.moves_that_day, s.bulk_move_day
FROM public.creative_stage_moves s
UNION ALL
SELECT 'upstack_new_customers'::text AS basis, s.family_key, s.tracker_row_id, s.product_slug, s.product_name, s.concept_id, s.display, s.ad_type, s.tracker_status, s.tracker_launch_date, s.cluster, s.icp, s.pain AS pain_point, s.data_start, s.data_through, s.path, s.began_in_testing, s.moved, s.first_day, s.testing_first_day, s.scaling_first_day, s.last_spend_day, s.scaling_last_day, s.days_in_test, s.launched_before_data_start, s.test_spend, s.test_purchases, s.test_revenue, s.test_link_clicks, s.test_days, s.test_after_spend, s.scale_spend, s.scale_purchases, s.scale_revenue, s.scale_link_clicks, s.scale_days, s.unclassified_spend, s.last7_spend, s.last7_purchases, s.last7_revenue, s.last7_scale_spend, s.last7_scale_purchases, s.last7_scale_revenue, s.live, s.live_scaling, s.moves_that_day, s.bulk_move_day
FROM public.creative_stage_moves_upstack_nc s
UNION ALL
SELECT 'upstack_all_orders'::text AS basis, s.family_key, s.tracker_row_id, s.product_slug, s.product_name, s.concept_id, s.display, s.ad_type, s.tracker_status, s.tracker_launch_date, s.cluster, s.icp, s.pain AS pain_point, s.data_start, s.data_through, s.path, s.began_in_testing, s.moved, s.first_day, s.testing_first_day, s.scaling_first_day, s.last_spend_day, s.scaling_last_day, s.days_in_test, s.launched_before_data_start, s.test_spend, s.test_purchases, s.test_revenue, s.test_link_clicks, s.test_days, s.test_after_spend, s.scale_spend, s.scale_purchases, s.scale_revenue, s.scale_link_clicks, s.scale_days, s.unclassified_spend, s.last7_spend, s.last7_purchases, s.last7_revenue, s.last7_scale_spend, s.last7_scale_purchases, s.last7_scale_revenue, s.live, s.live_scaling, s.moves_that_day, s.bulk_move_day
FROM public.creative_stage_moves_upstack_all s;

-- Where a creative that moved to scaling scales: its scaling campaign and ad set since the move, with spend and results, in three bases.
CREATE OR REPLACE VIEW analytics.creative_scaling_placements AS
SELECT 'meta'::text AS basis, p.family_key, p.campaign_id, p.campaign AS campaign_name, p.adset_id, p.adset AS adset_name, p.ads, p.spend, p.purchases, p.revenue, p.first_day, p.last_day
FROM public.creative_scaling_placements p
UNION ALL
SELECT 'upstack_new_customers'::text AS basis, p.family_key, p.campaign_id, p.campaign AS campaign_name, p.adset_id, p.adset AS adset_name, p.ads, p.spend, p.purchases, p.revenue, p.first_day, p.last_day
FROM public.creative_scaling_placements_upstack_nc p
UNION ALL
SELECT 'upstack_all_orders'::text AS basis, p.family_key, p.campaign_id, p.campaign AS campaign_name, p.adset_id, p.adset AS adset_name, p.ads, p.spend, p.purchases, p.revenue, p.first_day, p.last_day
FROM public.creative_scaling_placements_upstack_all p;

-- Benchmarks of the Test to scale page: creatives, spend, purchases and revenue by basis, product and period.
CREATE OR REPLACE VIEW analytics.creative_scaling_benchmarks AS
SELECT b.basis,
       b.product_slug,
       b.day_from,
       b.day_to,
       b.creatives,
       b.spend,
       b.purchases,
       b.revenue
FROM public.scaling_benchmarks b;

-- The copy and transcript Meta actually runs for each creative family (no image or video bytes).
CREATE OR REPLACE VIEW analytics.creative_content AS
SELECT c.family_key,
       c.meta_body,
       c.meta_title,
       c.meta_desc,
       c.transcript,
       c.transcript_seconds,
       c.story_url,
       c.is_video,
       c.ad_id,
       c.video_id,
       c.source
FROM public.family_content c;


-- ---------------------------------------------------------------------------------------------------------------- tags: products, taxonomy, tags, hooks

-- The products and the tag set each one uses.
CREATE OR REPLACE VIEW analytics.tag_products AS
SELECT p.id AS product_id,
       p.slug,
       p.name,
       p.tracker_names,
       p.meta_regex,
       p.meta_priority,
       p.tag_set,
       p.sort_order,
       p.active
FROM public.products p;

-- The Communication Overview lines: one per ICP x pain point, with the cluster, emotional trigger and story, per product.
CREATE OR REPLACE VIEW analytics.tag_taxonomy_lines AS
SELECT l.id AS line_id,
       p.slug AS product_slug,
       l.line_code,
       l.cluster,
       l.icp,
       l.pain_point,
       l.emotional_trigger,
       l.story,
       l.cluster_color,
       l.sort_order,
       l.added_after_tagging
FROM public.taxonomy_lines l
JOIN public.products p ON p.id = l.product_id;

-- The ingredients that address each taxonomy line: what each one attacks and supports.
CREATE OR REPLACE VIEW analytics.tag_line_ingredients AS
SELECT i.id AS ingredient_id,
       i.line_id,
       p.slug AS product_slug,
       l.line_code,
       i.ingredient,
       i.attacks,
       i.supports,
       i.sort_order
FROM public.line_ingredients i
JOIN public.taxonomy_lines l ON l.id = i.line_id
JOIN public.products p ON p.id = l.product_id;

-- Every tag ever written to a tracker row (current and superseded), joined to the tracker row, product and taxonomy line.
CREATE OR REPLACE VIEW analytics.tracker_tags AS
SELECT g.id AS tag_id,
       g.tracker_row_id,
       t.concept_id,
       t.family_key,
       p.slug AS product_slug,
       g.tag_set,
       g.version,
       g.is_current,
       g.line_id,
       tl.line_code,
       g.cluster,
       g.icp,
       g.pain_point,
       g.emotional_trigger,
       g.confidence,
       g.method,
       g.seen,
       g.why,
       g.runner_up,
       g.copy_only_line,
       g.tagger,
       g.tagged_at
FROM public.ad_tags g
JOIN public.tracker_rows t ON t.id = g.tracker_row_id AND t.deleted_at IS NULL
JOIN public.products p ON p.id = t.product_id
LEFT JOIN public.taxonomy_lines tl ON tl.id = g.line_id;

-- The hook of each tracker row: first spoken line and first on-screen text, joined to the tracker row and product.
CREATE OR REPLACE VIEW analytics.tracker_hooks AS
SELECT h.tracker_row_id,
       t.concept_id,
       t.family_key,
       p.slug AS product_slug,
       h.hook,
       h.spoken,
       h.on_screen,
       h.hook_source,
       h.confidence,
       h.note,
       h.version,
       h.extractor,
       h.extracted_at
FROM public.ad_hooks h
JOIN public.tracker_rows t ON t.id = h.tracker_row_id AND t.deleted_at IS NULL
JOIN public.products p ON p.id = t.product_id;


-- ---------------------------------------------------------------------------------------------------------------- priorities: the weekly creative priorities list

-- One row per weekly creative priorities snapshot: when it was built, the data it used and how many rows it holds.
CREATE OR REPLACE VIEW analytics.priorities_snapshots AS
SELECT s.week_start,
       s.built_at,
       s.data_through,
       s.basis,
       CASE WHEN jsonb_typeof(s.rows) = 'array' THEN jsonb_array_length(s.rows) END AS row_count
FROM public.creative_priorities_snapshots s;

-- Every threshold and weight the snapshot was scored with, one row per (week, name).
CREATE OR REPLACE VIEW analytics.priorities_thresholds AS
SELECT s.week_start,
       t.key   AS name,
       t.value AS value
FROM public.creative_priorities_snapshots s
CROSS JOIN LATERAL jsonb_each_text(CASE WHEN jsonb_typeof(s.thresholds) = 'object' THEN s.thresholds ELSE '{}'::jsonb END) t;

-- The product averages each line is compared with (ROAS, CPA, hit rate, spend, funnel counts), one numeric row per (week, product, metric).
CREATE OR REPLACE VIEW analytics.priorities_baselines AS
SELECT s.week_start,
       b.key AS product_slug,
       m.key AS metric,
       (m.value #>> '{}')::numeric AS value
FROM public.creative_priorities_snapshots s
CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(s.baselines) = 'object' THEN s.baselines ELSE '{}'::jsonb END) b
CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(b.value) = 'object' THEN b.value ELSE '{}'::jsonb END) m
WHERE jsonb_typeof(m.value) = 'number';

-- Every row of every weekly priorities snapshot, flattened: the line (cluster, ICP, pain point), its action section and status, score and the numbers behind it.
CREATE OR REPLACE VIEW analytics.priorities_concepts AS
SELECT s.week_start,
       r ->> 'product' AS product_slug,
       r ->> 'section' AS section,
       r ->> 'status' AS status,
       CASE WHEN jsonb_typeof(r #> '{rank}') = 'number' THEN (r #>> '{rank}')::numeric END AS rank,
       r ->> 'line_code' AS line_code,
       r ->> 'cluster' AS cluster,
       r ->> 'icp' AS icp,
       r ->> 'pain_point' AS pain_point,
       r ->> 'emotional_trigger' AS emotional_trigger,
       r ->> 'story' AS story,
       CASE WHEN jsonb_typeof(r #> '{concepts}') = 'number' THEN (r #>> '{concepts}')::int END AS concepts,
       CASE WHEN jsonb_typeof(r #> '{score}') = 'number' THEN (r #>> '{score}')::numeric END AS score,
       r ->> 'confidence' AS confidence,
       CASE WHEN jsonb_typeof(r -> 'flags') = 'array' THEN (SELECT string_agg(f, '; ') FROM jsonb_array_elements_text(r -> 'flags') f) END AS flags,
       r ->> 'why' AS why,
       COALESCE((r ->> 'manual') = 'true', false) AS is_manual,
       CASE WHEN jsonb_typeof(r #> '{metrics,spend}') = 'number' THEN (r #>> '{metrics,spend}')::numeric END AS spend,
       CASE WHEN jsonb_typeof(r #> '{metrics,purchases}') = 'number' THEN (r #>> '{metrics,purchases}')::numeric END AS purchases,
       CASE WHEN jsonb_typeof(r #> '{metrics,roas}') = 'number' THEN (r #>> '{metrics,roas}')::numeric END AS roas,
       CASE WHEN jsonb_typeof(r #> '{metrics,cpa}') = 'number' THEN (r #>> '{metrics,cpa}')::numeric END AS cpa,
       CASE WHEN jsonb_typeof(r #> '{metrics,roas_index}') = 'number' THEN (r #>> '{metrics,roas_index}')::numeric END AS roas_index,
       CASE WHEN jsonb_typeof(r #> '{metrics,ads}') = 'number' THEN (r #>> '{metrics,ads}')::int END AS ads,
       CASE WHEN jsonb_typeof(r #> '{metrics,judged}') = 'number' THEN (r #>> '{metrics,judged}')::int END AS judged,
       CASE WHEN jsonb_typeof(r #> '{metrics,hits}') = 'number' THEN (r #>> '{metrics,hits}')::int END AS hits,
       CASE WHEN jsonb_typeof(r #> '{metrics,mature}') = 'number' THEN (r #>> '{metrics,mature}')::int END AS mature,
       CASE WHEN jsonb_typeof(r #> '{metrics,hit_rate}') = 'number' THEN (r #>> '{metrics,hit_rate}')::numeric END AS hit_rate,
       CASE WHEN jsonb_typeof(r #> '{metrics,hit_rate_index}') = 'number' THEN (r #>> '{metrics,hit_rate_index}')::numeric END AS hit_rate_index,
       CASE WHEN jsonb_typeof(r #> '{metrics,spend_30d}') = 'number' THEN (r #>> '{metrics,spend_30d}')::numeric END AS spend_30d,
       CASE WHEN jsonb_typeof(r #> '{metrics,roas_30d}') = 'number' THEN (r #>> '{metrics,roas_30d}')::numeric END AS roas_30d,
       CASE WHEN jsonb_typeof(r #> '{metrics,spend_14d}') = 'number' THEN (r #>> '{metrics,spend_14d}')::numeric END AS spend_14d,
       CASE WHEN jsonb_typeof(r #> '{metrics,roas_14d}') = 'number' THEN (r #>> '{metrics,roas_14d}')::numeric END AS roas_14d,
       CASE WHEN jsonb_typeof(r #> '{metrics,nc_roas}') = 'number' THEN (r #>> '{metrics,nc_roas}')::numeric END AS nc_roas,
       CASE WHEN jsonb_typeof(r #> '{metrics,nc_cpa}') = 'number' THEN (r #>> '{metrics,nc_cpa}')::numeric END AS nc_cpa,
       CASE WHEN jsonb_typeof(r #> '{metrics,nc_purchases}') = 'number' THEN (r #>> '{metrics,nc_purchases}')::numeric END AS nc_purchases,
       CASE WHEN jsonb_typeof(r #> '{metrics,live_ads}') = 'number' THEN (r #>> '{metrics,live_ads}')::int END AS live_ads,
       CASE WHEN jsonb_typeof(r #> '{metrics,funnel,launched}') = 'number' THEN (r #>> '{metrics,funnel,launched}')::int END AS ads_launched,
       CASE WHEN jsonb_typeof(r #> '{metrics,funnel,under_tested}') = 'number' THEN (r #>> '{metrics,funnel,under_tested}')::int END AS ads_under_100_spend,
       CASE WHEN jsonb_typeof(r #> '{metrics,funnel,tested}') = 'number' THEN (r #>> '{metrics,funnel,tested}')::int END AS ads_100_plus_spend,
       CASE WHEN jsonb_typeof(r #> '{metrics,funnel,top}') = 'number' THEN (r #>> '{metrics,funnel,top}')::int END AS ads_10k_plus_spend
FROM public.creative_priorities_snapshots s
CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(s.rows) = 'array' THEN s.rows ELSE '[]'::jsonb END) r;

-- Concepts typed in by hand on the priorities page (not scored): product, section, line, why now and status.
CREATE OR REPLACE VIEW analytics.priorities_manual_concepts AS
SELECT m.id AS manual_id,
       m.product,
       m.section,
       m.cluster,
       m.icp,
       m.pain_point,
       m.story,
       m.notes,
       m.why_now,
       m.status,
       m.new_cluster,
       m.new_icp,
       m.new_pain_point,
       m.new_story,
       m.created_at,
       m.updated_at,
       m.done_at
FROM public.creative_priorities_manual m;


-- ---------------------------------------------------------------------------------------------------------------- production: concepts given to vendors

-- One concept given to one vendor for one week: the line, the brief and creative links and the timestamps of each step (who made the change is not exposed).
CREATE OR REPLACE VIEW analytics.production_assignments AS
SELECT a.id AS assignment_id,
       a.concept_key,
       a.product,
       a.vendor,
       a.line_id,
       a.manual_id,
       a.line_code,
       a.cluster,
       a.icp,
       a.pain_point,
       a.story,
       a.section_at_assign,
       a.format_code,
       a.note,
       a.vendor_note,
       a.for_week,
       a.brief_url,
       a.creative_url,
       a.brief_at,
       a.creative_at,
       a.ready_at,
       a.launched_at,
       a.dropped_at,
       a.tracker_concept_ids,
       CASE WHEN a.dropped_at IS NOT NULL THEN 'dropped'
            WHEN a.launched_at IS NOT NULL THEN 'launched'
            WHEN a.ready_at IS NOT NULL THEN 'ready'
            WHEN a.creative_url IS NOT NULL THEN 'creative_in'
            WHEN a.brief_url IS NOT NULL THEN 'brief_sent'
            ELSE 'assigned' END AS stage_from_assignment,
       a.created_at,
       a.updated_at
FROM public.creative_priorities_assignments a;

-- The creative formats (static, 15 s video, ...) an assignment can carry.
CREATE OR REPLACE VIEW analytics.production_formats AS
SELECT f.code AS format_code,
       f.name,
       f.length,
       f.sort,
       f.active
FROM public.creative_formats f;


-- ---------------------------------------------------------------------------------------------------------------- competitors: Meta Ad Library tracking

-- The competitor brands tracked in the Meta Ad Library and when each was last read.
CREATE OR REPLACE VIEW analytics.competitor_brands AS
SELECT b.brand,
       b.product_type,
       b.search_phrases,
       b.name_match,
       b.active,
       b.last_attempt_at,
       b.last_ok_at,
       b.last_ad_count
FROM public.competitor_brands b;

-- Weekly snapshot of each competitor ad found in the Meta Ad Library: format, copy, hook, how long it has been running.
CREATE OR REPLACE VIEW analytics.competitor_ads AS
SELECT a.week_start,
       a.library_id,
       a.brand,
       a.advertiser,
       a.start_date,
       a.days_running,
       a.variant_count,
       a.format,
       a.primary_text,
       a.headline,
       a.hook,
       a.landing_url,
       a.concept_key,
       a.seen_on,
       a.carried_from
FROM public.competitor_ads a;

-- Competitor ads grouped into concepts per week and mapped to our product, line, cluster, ICP and pain point (or flagged as a new angle).
CREATE OR REPLACE VIEW analytics.competitor_concepts AS
SELECT c.week_start,
       c.brand,
       c.concept_key,
       c.first_ad_start_date,
       c.days_running,
       c.variant_count,
       c.format,
       c.hook,
       c.primary_text_excerpt,
       c.mapped_product,
       c.line_code,
       c.cluster,
       c.icp,
       c.pain_point,
       c.confidence,
       c.is_new_angle,
       c.new_angle_label,
       c.as_of,
       c.is_stale
FROM public.competitor_concepts c;


-- A reader role created before this migration (etl.reader_role, default name analytics_reader) is granted the new views here; a role created later gets them from
-- reader_role.create, and ALTER DEFAULT PRIVILEGES covers views added after that. A database without that role skips this.
DO $grant$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'analytics_reader') THEN
    GRANT USAGE ON SCHEMA analytics TO analytics_reader;
    GRANT SELECT ON ALL TABLES IN SCHEMA analytics TO analytics_reader;
  END IF;
END
$grant$;

-- ---------------------------------------------------------------- comments
-- analytics.catalog and analytics.metric_glossary: generated from docs/schema/descriptions.py (domains, descriptions, grains, METRICS)
CREATE OR REPLACE VIEW analytics.catalog AS
SELECT 'meta_ads'::text AS view_name, 'marketing'::text AS domain, 'Dimension: one row per Meta ad (every ad the pipeline has ever seen: 42K, most ARCHIVED or DELETED) with its campaign, ad set, product, status and all-time totals. Join to the daily views on ad_id (they already carry the main names).'::text AS description, 'one row per Meta ad_id'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = 'public.meta_ads'::regclass) AS row_estimate
UNION ALL
SELECT 'meta_ad_daily'::text AS view_name, 'marketing'::text AS domain, 'The main Meta fact view: one row per Meta ad per day with Meta-reported results AND Upstack-attributed new customers / orders side by side, plus the ad''s names, campaign, ad set, stage and product. Roll up from here; never add purchases to Google''s.'::text AS description, 'one row per (day, ad_id)'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = 'public.ad_daily'::regclass) AS row_estimate
UNION ALL
SELECT 'meta_adset_daily'::text AS view_name, 'marketing'::text AS domain, 'Ad set x day roll-up of meta_ad_daily (Meta-reported and Upstack bases side by side).'::text AS description, 'one row per (day, adset_id)'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = 'public.ad_daily'::regclass) AS row_estimate
UNION ALL
SELECT 'meta_campaign_daily'::text AS view_name, 'marketing'::text AS domain, 'Campaign x day roll-up of meta_ad_daily (Meta-reported and Upstack bases side by side).'::text AS description, 'one row per (day, campaign_id)'::text AS grain, (SELECT min(day) FROM public.ad_daily)::date AS first_day, (SELECT max(day) FROM public.ad_daily)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = 'public.ad_daily'::regclass) AS row_estimate
UNION ALL
SELECT 'meta_campaign_daily_history'::text AS view_name, 'marketing'::text AS domain, 'Meta campaign x day back to 2024-12-31: the only Meta data before 2026-05-06 (campaign grain, no ad sets or ads). From 2026-05-06 on it equals meta_campaign_daily''s Meta-reported columns.'::text AS description, 'one row per (day, campaign_id) after the day rule (a day is read from ''app'' when it has app rows, else from ''sheet'')'::text AS grain, (SELECT min(day) FROM public.proj_feed_meta_day)::date AS first_day, (SELECT max(day) FROM public.proj_feed_meta_day)::date AS last_day, (SELECT NULLIF(c.reltuples, -1)::bigint FROM pg_class c WHERE c.oid = 'public.proj_feed_meta_day'::regclass) AS row_estimate
UNION ALL
