SELECT 'catalog'::text AS view_name, 'pipeline'::text AS domain, 'One row per analytics view: its domain, what it is, its grain, the first and last day it covers where it has days, and a row-count estimate. Start here to find which view answers a question.'::text AS description, 'one row per analytics view (this view itself is listed too)'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate
UNION ALL
SELECT 'metric_glossary'::text AS view_name, 'pipeline'::text AS domain, 'The canonical definition of every headline metric (ROAS, CPA, NC ROAS, CPM, frequency, hit rate, payback, ...): formula, the view and columns that hold the inputs, the default basis, the other bases and the traps. The same rows as the ''metrics'' key of docs/schema.json.'::text AS description, 'one row per metric name'::text AS grain, NULL::date AS first_day, NULL::date AS last_day, NULL::bigint AS row_estimate;

CREATE OR REPLACE VIEW analytics.metric_glossary AS
SELECT g.name::text, g.label::text, g.formula::text, g.source::text, g.default_basis::text, g.other_bases, g.traps, g.domain::text
FROM (VALUES
  ('spend', 'Ad spend', 'sum(spend) over the days. Total spend = Meta spend + Google spend; a ratio''s spend is always the sum over the same days and rows as its numerator.', 'analytics.meta_ad_daily.spend; analytics.google_campaign_daily.spend; analytics.platform_daily.spend', 'Meta (Graph API, both ad accounts) + Google Ads, platform-reported dollars: the ''Total spend'' of the Marketing metrics app (app/trends.py build_catalog(), total_spend).', ARRAY['Meta spend alone (the product bands'' Total column divides by it)', 'Business-wide spend in pacing = Meta + Google + TikTok and other platforms + Amazon ads (app/projection/pacing/catalog.py, biz_total_spend)', 'analytics.platform_daily_history.spend for days before 2026-05-06 (Meta ad level starts 2026-05-06; campaign grain from 2024-12-31 in analytics.meta_campaign_daily_history)']::text[], ARRAY['Spend adds across platforms; purchases and revenue never do.', 'Meta days are each ad account''s own day (Main = Los Angeles, BackUp = New York); Google, Upstack and orders are Pacific days.', 'The last 3-7 days still move (Meta restates), and today is never loaded.']::text[], 'marketing'),
  ('meta_purchases', 'Meta-reported purchases', 'sum(meta_purchases): purchases Meta reports for the ad that day (omni_purchase, else purchase, else pixel purchase), Meta''s default attribution.', 'analytics.meta_ad_daily.meta_purchases; analytics.meta_campaign_daily.meta_purchases', 'Meta-reported (counts returning customers, Meta''s attribution window)', ARRAY['Upstack new customers (analytics.meta_ad_daily.upstack_new_customers): first orders only', 'Upstack all orders (upstack_orders): every order Upstack credits']::text[], ARRAY['Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).', 'Meta and Google credit the same orders: never add Meta purchases to Google''s.', 'Meta counts a returning customer''s order as a purchase; it is not a new customer.']::text[], 'marketing'),
  ('meta_roas', 'Meta ROAS (platform ROAS)', 'sum(meta_revenue) / sum(spend): Meta-reported purchase value over spend, as a ratio of sums.', 'analytics.meta_ad_daily.meta_revenue,spend; analytics.meta_campaign_daily.meta_revenue,spend', 'Meta-reported purchase value / Meta spend', ARRAY['Upstack new-customer ROAS (upstack_nc_roas)', 'Upstack all-orders ROAS (upstack_all_orders_roas)', 'Total NC ROAS (total_nc_roas): actual new-customer revenue over total spend']::text[], ARRAY['Never average daily ROAS: divide the sums.', 'Meta ROAS counts returning customers and runs well above Total NC ROAS: they answer different questions.', 'Creative-level ROAS in analytics.creative_family_metrics / priorities_concepts is the same Meta-reported ratio but over each ad''s life since launch (blank under $100 spend in the priorities snapshot).']::text[], 'marketing'),
  ('meta_cpa', 'Meta cost per purchase', 'sum(spend) / sum(meta_purchases).', 'analytics.meta_ad_daily.spend,meta_purchases', 'Meta-reported purchases', ARRAY['Upstack new-customer CPA over Meta spend (spend / upstack_new_customers)', 'Total NC CPA (nc_cpa): total spend / actual new customers']::text[], ARRAY['Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).', 'This is not the NC CPA the business quotes (that one divides by actual new customers, see nc_cpa).']::text[], 'marketing'),
  ('upstack_new_customers', 'Upstack-attributed new customers', 'sum(upstack_new_customers): first-time customers Upstack credits to the ad under any-click, 30-day attribution (utm_source ''Meta Ads'').', 'analytics.meta_ad_daily.upstack_new_customers; analytics.google_campaign_daily.upstack_new_customers', 'Upstack new customers (first orders only, any-click 30-day, Pacific days)', ARRAY['Upstack all orders (upstack_orders): every order credited, returning included', 'Last-click by source (analytics.attribution_source_daily): exclusive per order, a different basis']::text[], ARRAY['NULL, not 0, on days Upstack was not pulled (Meta before 2026-05-06, Google before 2025-05-13).', 'Any-click credits an ad on days it spent nothing (spend = 0, upstack_* > 0 is normal); one customer can be credited to several ads, so sums over ads of different families can exceed orders_daily.new_customers.', 'About 1.3% of credited orders match no Meta ad (analytics.attribution_unmapped_daily): in orders_daily, in no ad row.', 'Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).']::text[], 'attribution'),
  ('upstack_nc_roas', 'Upstack new-customer ROAS (attributed)', 'sum(upstack_new_customer_revenue) / sum(spend) over the rows where Upstack was pulled (upstack_new_customers IS NOT NULL).', 'analytics.meta_ad_daily.upstack_new_customer_revenue,spend; analytics.google_campaign_daily.upstack_new_customer_revenue,spend', 'Upstack new customers (the default basis everywhere in the Marketing metrics app: ''Count: New customers'')', ARRAY['Upstack all orders (upstack_all_orders_roas)', 'Meta-reported (meta_roas)']::text[], ARRAY['Never compare Upstack new customers with Meta''s all purchases: Meta counts returning customers, Upstack''s new-customer basis does not (they are different quantities, not one number measured twice).', 'Restrict spend to days Upstack covers or the ratio is diluted by uncovered days.', 'When one ad is copied into several ad sets under one name, Upstack''s credit is split by Meta spend that day: family and higher sums are exact, one copy''s own numbers are an allocation.', 'Attribution, not the actual: the business''s real new-customer revenue is orders_daily (see nc_revenue / total_nc_roas).']::text[], 'attribution'),
  ('upstack_all_orders_roas', 'Upstack all-orders ROAS (attributed)', 'sum(upstack_order_revenue) / sum(spend) over the rows where Upstack was pulled.', 'analytics.meta_ad_daily.upstack_order_revenue,spend; analytics.google_campaign_daily.upstack_order_revenue,spend', 'Upstack all orders (every order Upstack credits to the ad, any-click 30 days)', ARRAY['Upstack new customers (upstack_nc_roas): the default basis', 'Meta-reported (meta_roas)']::text[], ARRAY['Use this only against Meta''s all-purchases basis, never against upstack_nc_roas.', 'Includes returning customers'' orders, so it flatters acquisition efficiency; the Marketing metrics app shows it only when ''Count: All orders'' is chosen.']::text[], 'attribution'),
  ('nc_revenue', 'New-customer revenue (actual)', 'sum(new_customer_revenue): first-order revenue per Pacific day, counted once (Upstack order-level measures).', 'analytics.orders_daily.new_customer_revenue; analytics.orders_by_product_daily.new_customer_revenue', 'Actual orders feed (analytics.orders_daily), gross: tax included, before refunds', ARRAY['By product (analytics.orders_by_product_daily): order total split across product lines by net line price', 'Attributed to Meta or Google (upstack_new_customer_revenue): an attribution, not the actual']::text[], ARRAY['Not the sum of platform columns: platforms overlap, this is counted once.', 'A day with no orders is absent from orders_daily, not 0.', 'Revenue is gross of tax and refunds (the Marketing metrics app describes it as ''tax included, before refunds''); net = total_revenue - tax - refunds in analytics.orders_daily_detail.', 'The trailing 7 days are restated nightly.']::text[], 'orders'),
  ('nc_orders', 'New customers (actual)', 'sum(new_customers): customers whose first Shopify order fell on the day, counted once.', 'analytics.orders_daily.new_customers; analytics.orders_by_product_daily.new_customers', 'Actual orders feed (analytics.orders_daily)', ARRAY['By product (orders whose largest product line is the product)', 'Upstack-attributed new customers (upstack_new_customers)']::text[], ARRAY['Not additive with attributed new customers: those credit the same customer to several ads or platforms.', 'Customers, not orders: a first order is the unit.']::text[], 'orders'),
  ('total_nc_roas', 'Total NC ROAS', 'sum(orders_daily.new_customer_revenue) / (sum(Meta spend) + sum(Google spend)) over the days that Meta, Google and orders_daily all cover, as a ratio of sums.', 'analytics.orders_daily.new_customer_revenue; analytics.platform_daily.spend', 'Actual new-customer revenue / Meta + Google spend (app/trends.py build_catalog(), nc_roas)', ARRAY['NC ROAS on Meta spend alone (meta_nc_roas in app/trends.py build_catalog()): the product bands'' Total column', 'Business-wide NC ROAS in pacing = (Shopify + Amazon new-customer revenue) / (Meta + Google + TikTok + other + Amazon ads) (app/projection/pacing/catalog.py, biz_nc_roas)', 'Per-product NC ROAS = analytics.orders_by_product_daily revenue / analytics.meta_product_daily spend']::text[], ARRAY['The numerator is actual revenue counted once, not the sum of the platforms'' purchase values.', 'Use only days all three sources cover and compute the ratio of sums, never an average of daily ratios.', 'Gross revenue (tax included, before refunds); the deal''s net-of-tax goal basis is lower.', 'Amazon is not in this ratio (the Marketing metrics app''s total covers Shopify, Meta and Google).']::text[], 'orders'),
  ('nc_cpa', 'NC CPA (cost per new customer)', '(sum(Meta spend) + sum(Google spend)) / sum(orders_daily.new_customers), over the days all three sources cover.', 'analytics.platform_daily.spend; analytics.orders_daily.new_customers', 'Total spend / actual new customers (app/trends.py build_catalog(), nc_cpa)', ARRAY['Meta spend / actual new customers (meta_nc_cpa): the product bands'' Total column', 'Testing / scaling NC CPA = stage spend / any-click new customers of that stage (analytics.attribution_anyclick_daily)', 'Upstack-attributed NC CPA = spend / upstack_new_customers (a different, attributed basis)']::text[], ARRAY['Divides by ACTUAL new customers, not by attributed ones or by Meta purchases.', 'Per-product NC CPA counts new customers whose largest product line is the product (analytics.orders_by_product_daily).']::text[], 'orders'),
  ('mer', 'MER (marketing efficiency ratio)', 'sum(total_revenue) / (sum(Meta spend) + sum(Google spend)) over the days all three sources cover.', 'analytics.orders_daily.total_revenue; analytics.platform_daily.spend', 'Orders feed total revenue (no Amazon) / Meta + Google spend (app/trends.py build_catalog(), mer)', ARRAY['Business-wide MER in pacing adds Amazon revenue and Amazon / TikTok / other spend (app/projection/pacing/catalog.py, biz_mer)']::text[], ARRAY['Total revenue here is gross (tax included, before refunds) and has no Amazon revenue; the matching spend has no Amazon or TikTok spend.']::text[], 'orders'),
  ('conversion_rate_uoc', 'Conversion rate on unique outbound clicks', 'actual new customers / Meta unique outbound clicks: per product = orders_by_product_daily.new_customers / meta_product_reach.unique_outbound_clicks; total = orders_daily.new_customers / meta_reach.unique_outbound_clicks.', 'analytics.orders_by_product_daily.new_customers; analytics.meta_product_reach.unique_outbound_clicks; analytics.orders_daily.new_customers; analytics.meta_reach.unique_outbound_clicks', 'Actual new customers / unique outbound clicks (app/projection/pacing/catalog.py, meta_cvr_<product> and prod_cvr_total; every click-based pacing metric uses UNIQUE OUTBOUND clicks)', ARRAY['Meta CVR = Meta purchases / Meta link clicks (meta_cvr)', 'NC conversion (clicks) = new customers / (Meta link clicks + Google clicks) (app/trends.py build_catalog(), nc_cvr_clicks)', 'NC conversion (visitors) = new customers / Upstack new visitors (analytics.site_traffic_daily): the Marketing metrics app''s nc_cvr']::text[], ARRAY['Unique outbound clicks exist only from 2026-07-05 (Meta serves filtered unique clicks ~120 days back); earlier periods are blank, not 0.', 'Unique clicks are not additive: read the row of the period''s own grain (day, week or month) in meta_reach / meta_product_reach.', 'The three products'' unique clicks add to 1.01-1.06x the account-level figure, so the product rates do not average to the total.', 'Meta''s total link_click count (analytics.meta_ad_daily.link_clicks) is a different, larger denominator than unique outbound clicks: do not mix the two.']::text[], 'marketing'),
  ('cpm', 'CPM (cost per 1,000 impressions)', 'sum(spend) / sum(impressions) x 1000.', 'analytics.meta_ad_daily.spend,impressions; analytics.meta_reach.impressions', 'Meta spend / Meta impressions x 1000 (app/trends.py build_catalog(), m_cpm)', ARRAY['Pacing divides spend by the account-level impressions pulled at the period''s own grain (app/projection/pacing/catalog.py, meta_cpm)', 'Cost per 1,000 reached = spend / reach x 1000 (a different, higher number)']::text[], ARRAY['Impressions add across days, reach does not: for CPM either source works, for frequency only meta_reach.', 'Meta days are the ad account''s own day.']::text[], 'marketing'),
  ('frequency', 'Frequency', 'impressions / reach, both taken at the SAME grain (a day''s, a week''s or a month''s own row): analytics.meta_reach.frequency.', 'analytics.meta_reach.impressions,reach,frequency', 'Account level, both ad accounts, at the grain you read (app/projection/pacing/catalog.py, meta_frequency)', ARRAY['No frequency exists per ad, ad set, campaign or product (reach is account level only)']::text[], ARRAY['Reach is de-duplicated by Meta and NOT additive: never average daily frequencies or sum daily reach to get a week or month; use the week / month rows.', 'The current day, week and month are partial.', 'Frequency here is the same-day overlap between ad sets, not exposure on more days.']::text[], 'marketing'),
  ('hit_rate', 'Creative hit rate', 'Display hit rate = ads whose since-launch spend reached $10,000 / launched ads (first tracker rows of an ad family with a launch date or any spend). Scoring hit rate = mature (>= 14 days old) judged ads (>= $100 spent) that reached $1,000 / mature judged ads, shrunk toward the product average.', 'analytics.creative_family_metrics.spend_launch,is_first_row,launch_date; analytics.priorities_concepts.ads_10k_plus_spend,ads_launched,hit_rate', 'Display: $10,000 since-launch spend over launched ads, Meta basis (etl/creative_priorities.py TOP_SPEND = 10000; the definition of a hit since 2026-11-10, docs/CREATIVE_PRIORITIES.md)', ARRAY['Scoring: HIT_SPEND = $1,000 over mature judged ads (priorities_concepts.hit_rate, hit_rate_index): the stored hit_rate in the snapshot and in the CSV export''s hit_rate / hit_rate_index columns', 'Hits out of tested ads: $10,000 / ads that spent $100 or more (hit_rate_10k_of_tested)']::text[], ARRAY['A KNOWN SPLIT: the displayed hit rate uses $10,000, but the priorities CSV export''s hit_rate and hit_rate_index columns (and the score''s hit-rate component) still use $1,000 (etl/creative_priorities.py: HIT_SPEND vs TOP_SPEND; docs/CREATIVE_PRIORITIES.md). Name which one you quote.', 'Launched counts every launched ad including recent ones with $0 spend; new ads need time to reach $10,000, so young cohorts read low.', 'Metrics sit on the FIRST tracker row of each ad family: filter is_first_row.']::text[], 'creative'),
  ('test_to_scale_rate', 'Test-to-scale rate (% reached scaling)', 'creatives that moved / creatives that began in testing, among creatives launched in the window and not launched before the data starts: count(*) FILTER (WHERE moved) / count(*) WHERE began_in_testing AND NOT launched_before_data_start AND first_day in window.', 'analytics.creative_stage_moves.moved,began_in_testing,launched_before_data_start,first_day,days_in_test', 'Meta basis (analytics.creative_stage_moves.basis = ''meta''); the basis changes only the money columns, never who moved (app/promotions.py _cohorts / build)', ARRAY['upstack_new_customers and upstack_all_orders: same creatives and moves, Upstack purchases and revenue']::text[], ARRAY['A creative MOVED only when it spent in a Testing campaign and first spent in a Scaling campaign on a LATER day (a campaign is Testing when its name contains ''test'').', 'Hide bulk days: 40 or more creatives entering scaling on one day (moves_that_day >= 40) is a mass relaunch, not a set of test winners.', 'Creatives that launched straight into scaling are not testers and never in the rate; a new creative needs time to move (analytics.creative_stage_moves.days_in_test): recent cohorts read low.', '''Held up'' = (scale_revenue / scale_spend) / (test_revenue / test_spend): held >= 0.90, softer >= 0.70, fell below; too early before $200 and 3 days in scaling.']::text[], 'creative'),
  ('repeat_revenue', 'Repeat revenue', 'Modeled: sum over cohorts of first-order revenue x curve[age] in the month at that age (age 0 = the acquisition month has no repeat): max(0, new_customers x first_order_per_customer x curve[age]) (app/projection/cohorts/engine.py repeat_for).', 'analytics.cohorts_monthly.first_order_revenue; analytics.cohorts_curve_cumulative.increment_ratio; analytics.cohorts_curve_goal.value', 'Modeled from the cohort table and the chosen retention curve (Live or Goal; scenario lever cohorts.curve_source in analytics.projection_levers)', ARRAY['Actual returning revenue = analytics.orders_daily.returning_customer_revenue (Upstack, gross)', 'Business-wide repeat = Shopify returning revenue + Amazon revenue not from new customers (app/projection/pacing/catalog.py, biz_repeat_rev)', 'Historical months come from the books (analytics.projection_actuals ''pnl.repeat_rev''); the model only projects forward']::text[], ARRAY['Repeat revenue is a projection driven by the curve choice; always say which curve (Live last N cohorts, Goal snapshot, as-of month).', 'The cohort table must hold only CLOSED months: a cell that lands in a month that is not over is blanked.', 'Gross of tax and refunds, like all pacing revenue.']::text[], 'cohorts'),
  ('retention_curve', 'Retention curve (Live vs Goal)', 'Repeat dollars per $1 of first-order revenue by age (months after acquisition). Live at age a = weighted average (weights new customers) of increment / first_order over the newest N cohorts that have a non-blank, non-zero increment at that age (usable_rank <= N); from age 28 on = previous age x 0.95. Goal = the newest saved snapshot of analytics.cohorts_curve_goal.', 'analytics.cohorts_curve_cumulative.increment_ratio,new_customers,usable_rank; analytics.cohorts_curve_goal.value,age,is_active', 'Live curve over the last 3 cohorts (app/projection/cohorts/engine.py Levers.n_cohorts = 3, tail_decay 0.95, tail_from_age 28)', ARRAY['Live over the last 6 cohorts (the P&L page offers 3 or 6; the deal notes mention 6; scenario lever cohorts.n_cohorts)', 'Goal curve (analytics.cohorts_curve_goal, is_active)', 'As-of curve: the Live curve re-derived from what was observable at the end of a past month', 'Blend: w x Goal + (1 - w) x Live']::text[], ARRAY['Say Live or Goal and N: the lifetime sums differ (compare sum(value) of the Goal curve with the Live curve you compute).', 'Never include a month that is not over; cohort exports differ by source (Shopify cohort dollars vs Upstack''s), so do not mix sources between refreshes.', 'Ages beyond 36 are the tail formula, not data.']::text[], 'cohorts'),
  ('payback', 'Payback (months)', 'First age (months after the first order, 0 = the first order pays) where cumulative contribution per new customer >= CAC. Inputs (aov, cac, product_cost_pct, fulfillment, max_age, curve) = analytics.projection_levers where module = ''financing'' and lever = ''payback'' (a json object holding only what the scenario sets; unset keys take the code defaults in app/projection/financing/params.py: product_cost_pct 0.1726, fulfillment 5.53, max_age 36, curve ''live''; aov and cac default to None = not typed). Contribution of the first order cm = AOV x (1 - product cost %) - fulfillment per order; month k adds cm x curve[k]; cumulative = cm + sum cm x curve.', 'analytics.projection_levers.module,lever,value; analytics.cohorts_curve_cumulative.increment_ratio; analytics.cohorts_monthly.cac,payback_months', 'Product margin: cost per order = product cost % x AOV + fulfillment (app/projection/financing/calc.py payback(); the quick hint app/projection/drivers/payback.py is the same arithmetic)', ARRAY['Fully loaded (''all variable costs''): cost per order = loaded_rate x AOV with the P&L''s own product, fulfillment, shipping, payment and chargeback rates (fully_loaded=True)', 'Interpolated months (months_interpolated) between the last unpaid and the first paid age', 'cohorts_monthly.payback_months: the payback exported with each cohort (a different, historical measure)']::text[], ARRAY['Payback on product margin is much shorter than fully loaded: always name the basis.', 'The curve behind it (Live N cohorts vs Goal) moves the answer by a month at some scales.', 'Contribution, not revenue: do not compare cumulative revenue with CAC.']::text[], 'cohorts'),
  ('gross_vs_net_revenue', 'Gross vs net revenue (pacing is gross)', 'Gross = total_revenue (tax included, before refunds). Net = total_revenue - tax - refunds. Plan basis = total_revenue - the plan''s sales-tax estimate (+ Amazon).', 'analytics.orders_daily.total_revenue; analytics.orders_daily_detail.total_revenue,tax,refunds', 'Gross: the pacing page, the P&L and every ROAS / MER here are gross; refunds are a memo row only (decision 2026-11-04)', ARRAY['Net of tax and refunds (app/projection/pacing/catalog.py, biz_total_rev_net)', 'Plan basis: Shopify total less the sales-tax estimate, plus Amazon: the basis of the P&L revenue goal (biz_total_rev_plan)']::text[], ARRAY['The monthly plan block and Month Snapshot compare against the P&L goal, which is net of the estimated sales tax (docs/projection/MODULE_pacing.md): comparing gross Shopify revenue with that goal overstates pacing.', 'Refunds are not deducted anywhere unless you subtract them (net = gross - tax - refunds): refunds were 11% of DTC revenue in Nov 1-2, so a net-of-refunds basis paced about 101% of goal, not 106% (docs/projection/MODULE_pacing.md, open items).']::text[], 'orders'),
  ('sales_tax_deduction', 'Sales-tax deduction (estimate)', 'Sales tax(m) = 0 for a month whose DTC revenue is loaded from the books (already net of tax), else -(sales_tax_rate x DTC revenue(m)); sales_tax_rate = analytics.projection_levers where module = ''drivers'' and lever = ''sales_tax_rate''; no row means the code default 0.07. It reduces total revenue.', 'analytics.projection_levers.module,lever,value; analytics.orders_daily_detail.tax', 'Estimate: 7% of DTC revenue for months not yet closed in the books (app/projection/drivers/revenue.py, drivers/model.py DEFAULT_SALES_TAX)', ARRAY['Actual tax collected (analytics.orders_daily_detail.tax), used by pacing''s net view', 'Closed books months carry no deduction']::text[], ARRAY['Open question (docs/projection/SKEPTIC_REPORT.md, SHEET_FINDINGS.md S1): the deduction applies from Jul-26 while history months carry none and the DTC revenue behind it is already net of tax; removing it adds about $535K to FY27 NOI. Settle against the Aug QuickBooks close or set drivers.sales_tax_rate to 0.', 'DTC rows of the pacing page stay gross on purpose; only the goal / projection total is net of the estimate.']::text[], 'projection'),
  ('repeat_share', 'Repeat share of revenue', 'sum(returning_customer_revenue) / sum(total_revenue).', 'analytics.orders_daily.returning_customer_revenue,total_revenue', 'Actual orders feed, Shopify only (app/trends.py build_catalog(), repeat_share)', ARRAY['Business-wide: (Shopify returning + Amazon non-new-customer revenue) / (Shopify + Amazon revenue) (app/projection/pacing/catalog.py, biz_repeat_share)']::text[], ARRAY['Gross of tax and refunds; no Amazon in the Shopify-only ratio.']::text[], 'orders')
) AS g(name, label, formula, source, default_basis, other_bases, traps, domain);

COMMENT ON SCHEMA analytics IS 'Read-only views over Lonvera''s data: marketing (Meta, Google), attribution, orders, creative, tags, priorities, production, projection, inventory, cohorts, pacing, competitors and pipeline. Start with catalog (every view with its domain, description, grain, first / last day), metric_glossary (the canonical metric definitions) and data_coverage (what is loaded through which day); read docs/AGENT_DATA_GUIDE.md. Rules: (1) name the basis: meta_* = Meta-reported, upstack_new_customer* = Upstack first orders (NC), upstack_order* = all Upstack-credited orders; (2) spend adds across Meta and Google, purchases and revenue never do; Total NC ROAS = orders_daily.new_customer_revenue / total spend of the same days; (3) the last loaded day is yesterday Pacific and the last 3-7 days still move; (4) upstack_* is NULL, not 0, on days Upstack was not pulled; (5) ratios from sums; creative_tracker metrics sit on the first row of each ad family.';
COMMENT ON VIEW analytics.orders_daily IS 'The business''s ACTUAL revenue and customers per Pacific day, counted once (Upstack order-level measures). new_customer_revenue is the numerator of Total NC ROAS. Grain: one row per Pacific day with orders. Source: public.upstack_orders_daily (Upstack /api/query, orders.* measures, America/Los_Angeles). Refresh: nightly (etl service 13:00 UTC): trailing 7 days replaced because Upstack restates recent days. Coverage: 2025-01-01 through yesterday (Pacific). Caveats: Revenue is the order total as Upstack reports it (tax included), before refunds: all numbers are gross. | There is no product, platform or campaign dimension: you cannot split new-customer revenue by product here. Use the attributed columns of the Meta / Google views (an attribution, not the actual) or analytics.orders_by_product_daily (the sheet''s NC Rev - By Product: actual first-order revenue by the order''s largest product line). | A day with no orders is absent, not zero. | new_customers is the count of first-time customers (first orders).';
COMMENT ON TABLE public.proj_feed_orders IS 'Shopify order totals by Pacific day (not ad-attributed): the sheet-fed twin of upstack_orders_daily with tax and refunds. Grain: one row per day. Source: the Lonvera Projections Google Sheet tab ''Orders - History'' (read by etl.projection_pacing). Refresh: nightly (etl service 13:00 UTC via etl.projection_daily): the trailing 14 days are replaced from the sheet tab; the `feeds` service (21:00 UTC) writes the shadow twin proj_feedx_* from the source API and compares. Coverage: 2025-01-01 through yesterday. Caveats: Values equal upstack_orders_daily for the shared columns; tax and refunds exist only here. analytics.orders_daily_detail exposes it with the tax and refunds columns; analytics.orders_daily carries the shared columns.';
COMMENT ON TABLE public.proj_feed_amazon IS 'Amazon.com + B2B sales and Amazon Ads (deduped v3 > v2 > v1) by purchase day. Grain: one row per day. Source: the Lonvera Projections Google Sheet tab ''Amazon - Daily'' (read by etl.projection_pacing); the direct feed reads ExpandFi merchant 1452. Refresh: nightly (etl service 13:00 UTC via etl.projection_daily): the trailing 14 days are replaced from the sheet tab; the `feeds` service (21:00 UTC) writes the shadow twin proj_feedx_* from the source API and compares. Coverage: 2024-09-24 through yesterday. Caveats: Amazon ad spend must be de-duplicated across Amazon''s v1 / v2 / v3 report generations (raw is about 1.3x high); this table already is. | Exposed as analytics.amazon_daily.';
COMMENT ON TABLE public.proj_feed_nc_product IS 'ACTUAL Shopify first-order revenue and new customers per Pacific day by the order''s largest product line (not Meta-attributed). The only product split of actual new-customer revenue. Grain: one row per (day, product). Source: the Lonvera Projections Google Sheet tab ''NC Rev - By Product'' (read by etl.projection_pacing); the direct feed reads ExpandFi merchant 1452 shopify_orders. Refresh: nightly (etl service 13:00 UTC via etl.projection_daily): the trailing 14 days are replaced from the sheet tab; the `feeds` service (21:00 UTC) writes the shadow twin proj_feedx_* from the source API and compares. Coverage: 2025-01-01 through today; product = VitaBull | Beef Liver | Boneflex | Other. Caveats: Exposed as analytics.orders_by_product_daily. Revenue = order total_price split across product lines by net line price; nc_orders = orders whose largest product line is the product.';
COMMENT ON TABLE public.proj_scenarios IS 'Named lever sets (scenarios) of the Projections module. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per scenario. Source: the Projections app. Refresh: on edit. Coverage: 7 scenarios incl. the default ''current''. Caveats: params holds the module levers (financing, drivers, cohorts...): finance data.';
COMMENT ON TABLE public.proj_series IS 'Typed monthly cells a scenario changes (''input'' replaces a constant, ''override'' replaces a computed month). Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (scenario, line, month). Source: the Projections app. Refresh: on edit. Coverage: 1.6K cells.';
COMMENT ON TABLE public.proj_actuals IS 'Scenario-independent monthly facts loaded from exports (QuickBooks lines, cohort rollups...). Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (line_key, month). Source: QuickBooks uploads and nightly roll-ups. Refresh: monthly upload / nightly. Coverage: 825 cells.';
COMMENT ON TABLE public.proj_audit IS 'Audit trail of every change made in the Projections module. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per change. Source: the Projections app. Refresh: on edit. Coverage: 494 rows.';
COMMENT ON TABLE public.proj_scenario_history IS 'Snapshot (params + series) of a scenario per version, newest 200 kept; used by restore. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (scenario, version). Source: the Projections app. Refresh: on edit. Coverage: 293 rows.';
COMMENT ON TABLE public.proj_refresh_runs IS 'One row per module per run of the nightly projection refresh. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per module run. Source: etl.projection_daily. Refresh: nightly. Coverage: 35 rows.';
COMMENT ON TABLE public.proj_cohorts IS 'Customer cohort table, one row per acquisition month (new customers, first-order $, CAC, repeat rate). Finance / planning inputs. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per cohort_month. Source: cohort export uploads. Refresh: monthly upload. Coverage: 33 cohorts. Caveats: Aggregates only. cac is a per-customer rate at full precision.';
COMMENT ON TABLE public.proj_cohort_cum IS 'Cumulative $ per cohort customer at each age (months after acquisition). Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (cohort_month, age). Source: cohort export uploads. Refresh: monthly upload. Coverage: 522 cells.';
COMMENT ON TABLE public.proj_cohort_uploads IS 'One row per cohort upload with the prior state, so the last upload can be undone. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per upload. Source: the Projections app. Refresh: on upload. Coverage: empty.';
COMMENT ON TABLE public.proj_curve_goal IS 'Goal retention curve snapshots (repeat $ per $1 of first-order revenue by age 1..60). Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (snapshot_id, age). Source: the Projections app. Refresh: on save. Coverage: 60 rows. Caveats: The newest snapshot is the active one.';
COMMENT ON TABLE public.proj_pnl_drivers IS 'How each P&L line is projected (segments of fixed / carry / rate modes). Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per line. Source: seeded from the sheet. Refresh: on edit. Coverage: 32 lines.';
COMMENT ON TABLE public.proj_pnl_settings IS 'P&L engine settings (rate window, inflation, headcount, COGS, EV). Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per setting. Source: the Projections app. Refresh: on edit. Coverage: 6 keys.';
COMMENT ON TABLE public.proj_pnl_cogs_sku IS 'Landed unit cost by SKU and the sales mix that weights it (the forward COGS model). Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per SKU. Source: typed inputs. Refresh: on edit. Coverage: 12 SKUs.';
COMMENT ON TABLE public.proj_pnl_qb_map IS 'QuickBooks account name -> P&L line key map. Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per account. Source: typed. Refresh: on edit. Coverage: 61 accounts.';
COMMENT ON TABLE public.proj_pnl_vendors IS 'Vendor retainers, current vs proposed, monthly. Reference only. Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per vendor. Source: typed. Refresh: on edit. Coverage: 10 vendors.';
COMMENT ON TABLE public.proj_upload_history IS 'Every QuickBooks upload commit with what it replaced, so the latest can be undone. Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per upload. Source: the Projections app. Refresh: on upload. Coverage: empty.';
COMMENT ON TABLE public.proj_po IS 'Purchase orders (planned and actual): units, vendor, dates, deposit state, unit cost. Finance / supply. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per purchase order. Source: the Projections app (manual and auto-plan). Refresh: on edit. Coverage: 74 rows. Caveats: Money (unit_cost) and vendor terms: finance. Exposed as analytics.inventory_purchase_orders (the link column is left out).';
COMMENT ON TABLE public.proj_fba_transfer IS 'Planned and actual transfers from the US warehouse to FBA. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per transfer. Source: the Projections app. Refresh: on edit. Coverage: 44 rows.';
COMMENT ON TABLE public.proj_vendor_lead IS 'Vendor lead times, minimum order quantities and default warehouses. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per vendor. Source: typed. Refresh: on edit. Coverage: 2 vendors.';
COMMENT ON TABLE public.proj_vendor_cogs IS 'Vendor unit costs per product and default deposit share. Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (vendor, product). Source: typed. Refresh: on edit. Coverage: 6 rows.';
COMMENT ON TABLE public.proj_product_cost IS 'Unit cost used to value stock on hand (China landed cost per SKU). Finance. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per product. Source: typed. Refresh: on edit. Coverage: 5 rows.';
COMMENT ON TABLE public.proj_reorder_param IS 'Reorder parameters per location and product (lead days, safety days, MOQ). Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (location, product). Source: typed. Refresh: on edit. Coverage: 8 rows.';
COMMENT ON TABLE public.proj_stock_snapshot IS 'Stock on hand per location and product, one row per count. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (location, product, as_of). Source: counts and 3PL portals. Refresh: manual. Coverage: 20 rows.';
COMMENT ON TABLE public.proj_supply_history IS 'One row per changed supply record (orders, transfers, stock, prices) with before and after, for revert / restore. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per changed record. Source: the Projections app. Refresh: on edit. Coverage: 4 rows.';
COMMENT ON TABLE public.proj_units_monthly IS 'Monthly units history for months older than the daily window (Amazon since Sep 2024). Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (location, product, month). Source: ExpandFi / typed. Refresh: rarely. Coverage: 96 rows.';
COMMENT ON TABLE public.proj_units_country IS 'International units by destination country and month (informational split of overseas 3PL volume). Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per (month, country). Source: the 3PL''s tracking exports. Refresh: monthly. Coverage: 108 rows.';
COMMENT ON TABLE public.proj_units_loads IS 'One row per units load (seed, refresh, upload): drives the freshness chips. Projection engine (finance / planning); read it through the analytics projection_* / inventory_* / cohorts_* views, never the raw table. Grain: one row per load. Source: the Projections app / feeds. Refresh: per load. Coverage: 18 rows.';
COMMENT ON VIEW analytics.attribution_source_daily IS 'Last-click attribution by ad source (Meta Ads, Google Ads, ...) per Pacific day: new customers and orders each source is credited with, exclusive per order. Grain: one row per (day, ad_source). Source: public.proj_feed_attribution (the Upstack last-click feed). Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2025-01-01 through yesterday. Caveats: Last-click is exclusive per order, unlike the any-click 30-day credit in meta_ad_daily / google_campaign_daily: the two bases do not agree and must not be mixed in one ratio.';
COMMENT ON COLUMN analytics.attribution_source_daily.day IS 'Pacific day.';
COMMENT ON COLUMN analytics.attribution_source_daily.ad_source IS 'Ad source label: ''Meta Ads'' | ''Google Ads'' | ...';
COMMENT ON COLUMN analytics.attribution_source_daily.new_customers IS 'New customers credited.';
COMMENT ON COLUMN analytics.attribution_source_daily.new_customer_revenue IS 'Their revenue.';
COMMENT ON COLUMN analytics.attribution_source_daily.orders IS 'All orders credited.';
COMMENT ON COLUMN analytics.attribution_source_daily.order_revenue IS 'Their revenue.';
COMMENT ON COLUMN analytics.attribution_source_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.attribution_anyclick_daily IS 'New customers Upstack credits to Scaling and to Testing Meta campaigns per day under any-click 30-day attribution. Grain: one row per (day, stage). Source: public.proj_feed_anyclick (the sheet tab ''Upstack Any-Click - By Campaign''). Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2025-05-08 through yesterday. Caveats: Any-click credits every Meta campaign the customer clicked in the 30 days before the order, so a customer can count under both stages across days; do not add to orders_daily.new_customers.';
COMMENT ON COLUMN analytics.attribution_anyclick_daily.day IS 'Day.';
COMMENT ON COLUMN analytics.attribution_anyclick_daily.stage IS '''Scaling'' | ''Testing''.';
COMMENT ON COLUMN analytics.attribution_anyclick_daily.new_customers IS 'New customers credited.';
COMMENT ON COLUMN analytics.attribution_anyclick_daily.new_customer_revenue IS 'Their first-order revenue.';
COMMENT ON COLUMN analytics.attribution_anyclick_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.attribution_unmapped_daily IS 'Upstack-credited orders the build could not tie to a Meta ad. They are inside orders_daily and inside no ad-level row of meta_ad_daily. Grain: one row per (day, campaign, ad). Source: public.upstack_unmapped_daily (rebuilt in full on every build). Refresh: nightly (etl service 13:00 UTC). Coverage: 2026-05-06 through yesterday. Caveats: reason: ''not_identified'' (no ad name / ''(not set)''), ''no_campaign'' (the campaign matches no Meta campaign), ''no_ad'' (campaign found, ad name not).';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.day IS 'Pacific day.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.campaign IS 'utm_campaign value.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.ad IS 'utm_ad value.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.reason IS 'not_identified | no_campaign | no_ad.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.new_customers IS 'New customers credited.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.new_customer_revenue IS 'Their first-order revenue, dollars.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.orders IS 'All orders credited.';
COMMENT ON COLUMN analytics.attribution_unmapped_daily.order_revenue IS 'Revenue, dollars.';
COMMENT ON VIEW analytics.orders_daily_detail IS 'orders_daily plus the tax collected and the refunds of each Pacific day: the two columns pacing uses to go from gross to net revenue. Grain: one row per day. Source: public.proj_feed_orders (Shopify order totals, Upstack). Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2025-01-01 through yesterday. Caveats: total_revenue is GROSS: tax included, before refunds. Net = total_revenue - tax - refunds. The pacing page and the P&L stay gross and show refunds as a memo only. | The columns shared with orders_daily carry the same values.';
COMMENT ON COLUMN analytics.orders_daily_detail.day IS 'Pacific day.';
COMMENT ON COLUMN analytics.orders_daily_detail.new_customer_revenue IS 'New-customer revenue.';
COMMENT ON COLUMN analytics.orders_daily_detail.returning_customer_revenue IS 'Returning-customer revenue.';
COMMENT ON COLUMN analytics.orders_daily_detail.new_customers IS 'New customers.';
COMMENT ON COLUMN analytics.orders_daily_detail.total_revenue IS 'Total revenue.';
COMMENT ON COLUMN analytics.orders_daily_detail.orders IS 'All orders.';
COMMENT ON COLUMN analytics.orders_daily_detail.tax IS 'Tax collected.';
COMMENT ON COLUMN analytics.orders_daily_detail.refunds IS 'Refunds.';
COMMENT ON COLUMN analytics.orders_daily_detail.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.orders_by_product_daily IS 'ACTUAL Shopify first-order revenue and new customers per Pacific day by the order''s largest product line (not Meta-attributed): the only product split of actual new-customer revenue. Grain: one row per (day, product). Source: public.proj_feed_nc_product (ExpandFi merchant 1452 shopify_orders, or the sheet tab ''NC Rev - By Product''). Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2025-01-01 through today; product = VitaBull | Beef Liver | Boneflex | Other. Caveats: Revenue = order total_price split across product lines by net line price, tax included, before refunds; new_customers = orders whose largest product line is the product. | Day sums equal orders_daily to within restatement.';
COMMENT ON COLUMN analytics.orders_by_product_daily.day IS 'Pacific day.';
COMMENT ON COLUMN analytics.orders_by_product_daily.product IS 'VitaBull | Beef Liver | Boneflex | Other.';
COMMENT ON COLUMN analytics.orders_by_product_daily.new_customer_revenue IS 'First-order revenue, dollars.';
COMMENT ON COLUMN analytics.orders_by_product_daily.new_customers IS 'First orders.';
COMMENT ON COLUMN analytics.orders_by_product_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.orders_hourly IS 'Actual new-customer revenue and first orders by Pacific day and clock hour: the share curve behind the ''NC revenue today'' card. Grain: one row per (day, hour) with at least one first order. Source: public.proj_feed_nc_hourly (ExpandFi warehouse shopify_orders). Refresh: feeds service 21:00 UTC, trailing 35 closed days. Coverage: from the first pull (a 60-day backfill once); today is never stored. Caveats: Sparse: an hour with no first order has no row. Revenue is tax included, before refunds.';
COMMENT ON COLUMN analytics.orders_hourly.day IS 'Pacific day of the first order.';
COMMENT ON COLUMN analytics.orders_hourly.hour IS 'Pacific wall-clock hour 0-23.';
COMMENT ON COLUMN analytics.orders_hourly.new_customer_revenue IS 'Sum of order total_price of the first orders in that hour (tax included, before refunds); test orders and orders without priced lines excluded.';
COMMENT ON COLUMN analytics.orders_hourly.new_customers IS 'Number of first orders in that hour.';
COMMENT ON COLUMN analytics.orders_hourly.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.amazon_daily IS 'Amazon.com + B2B sales and Amazon Ads (de-duplicated across v1 / v2 / v3 report generations) by purchase day. Grain: one row per day. Source: public.proj_feed_amazon (ExpandFi merchant 1452 sales table, or the sheet tab ''Amazon - Daily''). Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2024-09-24 through yesterday (about a 2-day lag). Caveats: Amazon is a separate channel: its revenue is not in orders_daily and its ad spend is not in platform_daily. Pacing''s business-wide totals add the two.';
COMMENT ON COLUMN analytics.amazon_daily.day IS 'Purchase day.';
COMMENT ON COLUMN analytics.amazon_daily.orders IS 'Orders.';
COMMENT ON COLUMN analytics.amazon_daily.units IS 'Units.';
COMMENT ON COLUMN analytics.amazon_daily.revenue IS 'Revenue.';
COMMENT ON COLUMN analytics.amazon_daily.new_customer_orders IS 'New-customer orders.';
COMMENT ON COLUMN analytics.amazon_daily.new_customer_revenue IS 'New-customer revenue.';
COMMENT ON COLUMN analytics.amazon_daily.ad_spend IS 'Amazon Ads spend (deduped).';
COMMENT ON COLUMN analytics.amazon_daily.attributed_sales IS 'Sales Amazon attributes to ads.';
COMMENT ON COLUMN analytics.amazon_daily.clicks IS 'Ad clicks.';
COMMENT ON COLUMN analytics.amazon_daily.impressions IS 'Ad impressions.';
COMMENT ON COLUMN analytics.amazon_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.site_traffic_daily IS 'Pixel-tracked visitors, new visitors and sessions per day (Upstack). Grain: one row per day. Source: public.proj_feed_traffic. Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2025-05-08 through today. Caveats: Visitors are unique within a day: summing days does not give unique visitors.';
COMMENT ON COLUMN analytics.site_traffic_daily.day IS 'Day.';
COMMENT ON COLUMN analytics.site_traffic_daily.new_visitors IS 'First-time visitors.';
COMMENT ON COLUMN analytics.site_traffic_daily.visitors IS 'Visitors.';
COMMENT ON COLUMN analytics.site_traffic_daily.sessions IS 'Sessions.';
COMMENT ON COLUMN analytics.site_traffic_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.platform_daily_history IS 'Meta and Google spend and platform-reported conversions per day from 2025-01-01 (Upstack ad-platform feed): the longest spend history in the database. Grain: one row per (day, platform). Source: public.proj_feed_platform. Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2025-01-01 through yesterday. Caveats: platform is normalised to ''meta'' | ''google'' (platform_label keeps Upstack''s text). Spend reconciles with meta_ad_daily and google_campaign_daily on the days they share. | own_purchases / own_revenue are platform-reported and overlap across platforms: never add them. TikTok has no rows.';
COMMENT ON COLUMN analytics.platform_daily_history.day IS 'Day.';
COMMENT ON COLUMN analytics.platform_daily_history.platform IS '''meta'' | ''google'' (normalised from platform_label).';
COMMENT ON COLUMN analytics.platform_daily_history.platform_label IS '''Meta (Facebook/Instagram)'' | ''Google Ads'' (TikTok has no rows).';
COMMENT ON COLUMN analytics.platform_daily_history.spend IS 'Spend, dollars.';
COMMENT ON COLUMN analytics.platform_daily_history.link_clicks IS 'Link clicks.';
COMMENT ON COLUMN analytics.platform_daily_history.clicks IS 'All clicks.';
COMMENT ON COLUMN analytics.platform_daily_history.own_purchases IS 'Platform-reported purchases.';
COMMENT ON COLUMN analytics.platform_daily_history.own_revenue IS 'Platform-reported conversion value.';
COMMENT ON COLUMN analytics.platform_daily_history.own_new_customer_purchases IS 'Platform-reported new-customer purchases (0 for Google).';
COMMENT ON COLUMN analytics.platform_daily_history.own_new_customer_revenue IS 'Their value.';
COMMENT ON COLUMN analytics.platform_daily_history.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.meta_product_daily IS 'Meta spend and link clicks per day by product, classified campaign name -> ad set name -> ad name -> Other. Grain: one row per (day, product) after the day rule. Source: public.proj_feed_meta_product. Refresh: nightly (app rows, trailing 14 days). Coverage: 2025-01-01 through yesterday. Caveats: A day is read from ''app'' rows when it has any, else from the sheet rows (the view applies this, so no day is counted twice). | Campaigns that mix products are split by their ad set and ad names where the campaign name is not enough, so this can differ from meta_ads.product_slug.';
COMMENT ON COLUMN analytics.meta_product_daily.day IS 'Day.';
COMMENT ON COLUMN analytics.meta_product_daily.product IS 'VitaBull | Beef Liver | Boneflex | Other.';
COMMENT ON COLUMN analytics.meta_product_daily.source IS '''app'' | ''sheet''.';
COMMENT ON COLUMN analytics.meta_product_daily.spend IS 'Spend.';
COMMENT ON COLUMN analytics.meta_product_daily.link_clicks IS 'Link clicks.';
COMMENT ON COLUMN analytics.meta_product_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.meta_product_reach IS 'Unique outbound clicks per product, de-duplicated across the product''s ad sets, at day / week / month grain: the only per-product reach-like metric. Grain: one row per (grain, period_key, product). Source: public.proj_feed_product_reach. Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: from 2026-07-05 (Meta serves filtered unique clicks about 120 days back); earlier periods are absent and never re-pulled. Caveats: Not additive across periods or products: read the row of the grain you want. The three products add to about 1.01-1.06x the account-level unique outbound clicks in meta_reach. | Reach and frequency per product do not exist, only unique outbound clicks.';
COMMENT ON COLUMN analytics.meta_product_reach.grain IS '''day'' | ''week'' | ''month''.';
COMMENT ON COLUMN analytics.meta_product_reach.period_key IS 'Period key.';
COMMENT ON COLUMN analytics.meta_product_reach.period_start IS 'First day.';
COMMENT ON COLUMN analytics.meta_product_reach.period_end IS 'Last day.';
COMMENT ON COLUMN analytics.meta_product_reach.product IS 'VitaBull | Beef Liver | Boneflex | Other.';
COMMENT ON COLUMN analytics.meta_product_reach.unique_outbound_clicks IS 'Unique outbound clicks de-duplicated across the product''s ad sets.';
COMMENT ON COLUMN analytics.meta_product_reach.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.meta_bids_daily IS 'Meta bid settings per day, summed: spend on cost-cap / bid-cap ad sets and on ROAS-floor ad sets, with the spend-weighted bid sums. Grain: one row per day. Source: public.proj_feed_bids (the sheet tab ''Meta Bids - Daily''). Refresh: nightly: the etl service (13:00 UTC, etl.projection_daily) replaces the trailing 14 days; the feeds service (21:00 UTC) writes the direct pull; see analytics.pipeline_feeds for each feed''s mode and last load. Coverage: 2026-04-28 through today; settings of past days are rebuilt from the account activity log, so older history cannot be pulled. Caveats: Average cost cap = sum(spend_times_cap) / sum(capped_spend); average ROAS floor = sum(spend_times_floor) / sum(floor_spend). Per-ad-set bids are not stored.';
COMMENT ON COLUMN analytics.meta_bids_daily.day IS 'Day.';
COMMENT ON COLUMN analytics.meta_bids_daily.spend IS 'Total spend.';
COMMENT ON COLUMN analytics.meta_bids_daily.capped_spend IS 'Spend on ad sets with a cost cap.';
COMMENT ON COLUMN analytics.meta_bids_daily.spend_times_cap IS 'Sum of spend x cap.';
COMMENT ON COLUMN analytics.meta_bids_daily.floor_spend IS 'Spend on ad sets with a ROAS floor.';
COMMENT ON COLUMN analytics.meta_bids_daily.spend_times_floor IS 'Sum of spend x floor.';
COMMENT ON COLUMN analytics.meta_bids_daily.loaded_at IS 'When loaded.';
COMMENT ON VIEW analytics.pacing_live_today IS 'Today''s Meta spend, Google spend, new-customer revenue and new customers so far, one snapshot per hourly pull from Upstack. Grain: one row per pull (pulled_at, to the minute). Source: public.proj_live_today_snapshots (etl.live_today). Refresh: Railway cron `live`, every hour on the hour. Coverage: from the first pull; history kept 90 days. Caveats: Upstack trails the ad platforms by 30-60 minutes, so the numbers are a floor of what was spent and sold; end-of-day projections made early in the day lean low. | Revenue is tax included, before refunds (gross).';
COMMENT ON COLUMN analytics.pacing_live_today.pulled_at IS 'When Upstack was asked, to the minute (UTC).';
COMMENT ON COLUMN analytics.pacing_live_today.day IS 'Pacific day the numbers belong to.';
COMMENT ON COLUMN analytics.pacing_live_today.pacific_time IS 'Pacific wall-clock time of the pull, to the minute.';
COMMENT ON COLUMN analytics.pacing_live_today.meta_spend IS 'Meta (Facebook / Instagram) spend so far that day, dollars, all ad accounts Upstack sees.';
COMMENT ON COLUMN analytics.pacing_live_today.google_spend IS 'Google Ads spend so far that day, dollars.';
COMMENT ON COLUMN analytics.pacing_live_today.total_spend IS 'Spend so far across every ad platform Upstack reports (Meta, Google, TikTok), dollars.';
COMMENT ON COLUMN analytics.pacing_live_today.new_customer_revenue IS 'New-customer revenue so far that day, dollars (orders.new_customer_total_revenue).';
COMMENT ON COLUMN analytics.pacing_live_today.new_customers IS 'New customers (first orders) so far that day.';
COMMENT ON VIEW analytics.pacing_amazon_month_to_date IS 'Completed Amazon month-to-date revenue, one snapshot per Pacific day and month: reported days plus the missing days projected at the trailing 7-day average of the reported days. Grain: one row per (snapshot_day, month). Source: public.proj_amazon_mtd_snapshots (etl.amazon_mtd), without the projected_days json. Refresh: after the Amazon feed load (feeds 21:00 UTC) and again in the etl service (13:00 UTC). Coverage: from the first run; history kept so each day''s projection can be compared with the final month. Caveats: projected_mtd is an estimate, never an actual; the projected days themselves (json) are left out, rebuild them from daily_rate and days_projected.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.snapshot_day IS 'Pacific day of the run.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.month IS 'First day of the month that was completed.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.computed_at IS 'When the run computed it (UTC).';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.data_through IS 'Last day that should have been complete at the run (yesterday by default).';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.last_actual_day IS 'Last day of the month with reported Amazon revenue; null before the first reported day.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.days_actual IS 'Calendar days from the 1st through the last reported day.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.days_projected IS 'Days after the last reported day, through data_through, that were projected (0 when the feed is current or stale).';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.daily_rate IS 'Dollars per projected day: mean of the last 7 reported days with revenue above zero (fewer when fewer exist).';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.actual_mtd IS 'Reported Amazon revenue from the 1st through the last reported day, dollars.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.projected_mtd IS 'actual_mtd plus the projected days plus any partial-day top-up, dollars.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.status IS 'complete (nothing to project), projected, stale (feed more than 5 days behind: nothing projected), no_rate (no revenue in the feed), no_days (month has no complete day).';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.method IS 'Rule and version that made the row, e.g. trailing-7-available/v1.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.flags IS 'Plain flags: feed_stale, short_window, window_has_gaps, gap_days_inside_month, newest_day_partial, no_data.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.partial_topup IS 'Dollars added because the newest reported day looked partial (below half the days before it); 0 otherwise.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.lag_days IS 'Days between data_through and the last reported day.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.rate_source IS 'trailing_7_available, or previous_month_last_7 when the month has no reported day yet.';
COMMENT ON COLUMN analytics.pacing_amazon_month_to_date.note IS 'The plain-language line the page shows.';
COMMENT ON VIEW analytics.pacing_hourly_spend_curve IS 'Meta time-of-day spend curve (the last 30 days'' hourly spend): the typed input behind the intraday projection. Grain: one row per hour of day (Pacific). Source: public.proj_pacing_hourly (typed from Meta Ads Manager''s time-of-day report). Refresh: manual. Coverage: 24 rows.';
COMMENT ON COLUMN analytics.pacing_hourly_spend_curve.hour IS 'Hour of day, Pacific (0-23).';
COMMENT ON COLUMN analytics.pacing_hourly_spend_curve.spend_30d IS 'Spend in that hour over the 30 days.';
COMMENT ON COLUMN analytics.pacing_hourly_spend_curve.days_in_curve IS 'Days in the curve.';
COMMENT ON COLUMN analytics.pacing_hourly_spend_curve.note IS 'Note.';
COMMENT ON COLUMN analytics.pacing_hourly_spend_curve.updated_at IS 'When updated.';
COMMENT ON VIEW analytics.pacing_levers IS 'The ratios and estimates the pacing page applies (for example the overseas-warehouse units ratio), one row per lever. Grain: one row per lever. Source: public.proj_feed_levers (the updated_by column is left out). Refresh: on change. Coverage: a handful of rows.';
COMMENT ON COLUMN analytics.pacing_levers.lever IS 'Lever name.';
COMMENT ON COLUMN analytics.pacing_levers.value IS 'Value (e.g. 0.905).';
COMMENT ON COLUMN analytics.pacing_levers.note IS 'Why / how it was fitted.';
COMMENT ON COLUMN analytics.pacing_levers.updated_at IS 'When changed.';
COMMENT ON VIEW analytics.pacing_meta_spend_monthly IS 'Monthly Meta spend from ad_daily, read by the projection drivers module. Grain: one row per month. Source: public.proj_meta_spend_monthly (a view over ad_daily). Refresh: live view. Coverage: 2026-05 onward. Caveats: A month is complete when days equals the days in the month.';
COMMENT ON COLUMN analytics.pacing_meta_spend_monthly.month IS 'First day of the month.';
COMMENT ON COLUMN analytics.pacing_meta_spend_monthly.spend IS 'Meta spend, dollars.';
COMMENT ON COLUMN analytics.pacing_meta_spend_monthly.days IS 'Days with any ad_daily row.';
COMMENT ON COLUMN analytics.pacing_meta_spend_monthly.last_day IS 'Last day with data.';
COMMENT ON VIEW analytics.pipeline_feeds IS 'One row per pacing feed: its mode (sheet / shadow / direct), what was last loaded and through which day. Grain: one row per feed. Source: public.proj_feed_runs joined to public.proj_feed_config. Refresh: each load. Coverage: about 12 feeds.';
COMMENT ON COLUMN analytics.pipeline_feeds.feed IS 'Feed key (primary key).';
COMMENT ON COLUMN analytics.pipeline_feeds.mode IS '''sheet'' | ''shadow'' | ''direct'' (no config row = ''sheet''): which source the app reads for the feed.';
COMMENT ON COLUMN analytics.pipeline_feeds.source IS '''sheet:<tab>'' | ''ad_daily'' | ''snapshot''.';
COMMENT ON COLUMN analytics.pipeline_feeds.loaded_at IS 'When last loaded.';
COMMENT ON COLUMN analytics.pipeline_feeds.rows_loaded IS 'Rows of the last load.';
COMMENT ON COLUMN analytics.pipeline_feeds.first_day IS 'First day loaded.';
COMMENT ON COLUMN analytics.pipeline_feeds.last_day IS 'Last day loaded.';
COMMENT ON COLUMN analytics.pipeline_feeds.note IS 'Free note.';
COMMENT ON VIEW analytics.pipeline_feed_attempts IS 'One row per direct pull attempt of a feed (any mode). Grain: one row per attempt. Source: public.proj_feed_attempts. Refresh: each feeds run (21:00 UTC). Coverage: since 2026-11-04.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.id IS 'Primary key.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.feed IS 'Feed key.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.mode IS 'Mode at the time.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.source IS '''api:upstack'' | ''api:warehance'' | ''api:meta'' | ''api:expandfi'' | ''sheet:<tab>''.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.started_at IS 'Start.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.finished_at IS 'Finish.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.status IS 'ok | failed | fallback | skipped.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.rows IS 'Rows pulled.';
COMMENT ON COLUMN analytics.pipeline_feed_attempts.first_day IS 'First day of the pull.';
