COMMENT ON COLUMN analytics.inventory_units_daily.location IS 'revamp (US 3PL, Warehance) | amazon (FBA) | intl (overseas 3PL).';
COMMENT ON COLUMN analytics.inventory_units_daily.product IS 'bull | liver | boneflex | belle | flow.';
COMMENT ON COLUMN analytics.inventory_units_daily.day IS 'Day.';
COMMENT ON COLUMN analytics.inventory_units_daily.units IS 'Units.';
COMMENT ON COLUMN analytics.inventory_units_daily.source IS '''warehance'' | ''expandfi'' | ''tracking-xlsx'' | ''estimate'' | ''upload''.';
COMMENT ON COLUMN analytics.inventory_units_daily.is_estimate IS 'true = modeled.';
COMMENT ON COLUMN analytics.inventory_units_daily.loaded_at IS 'When loaded.';
